COLLNT("muwattaansar",{"560":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کا ایک فتویٰ مذکور ہے۔","...... میت کے تین قسم کے بہن بھائی ہوتے ہیں جن کا گزشتہ باب میں تذکرہ ہو چکا ہے، ماں کی طرف سے بہن بھائیوں کو اخیافی، مادری اور بنی الام بھی کہتے ہیں۔ یہ بہن بھائی اصحاب الفرائض میں شامل ہیں۔ ورثاء کے متعلق یہ ایک اصول ہے کہ جس رشتہ دار کو میت کے ساتھ جوڑنے والا واسطہ درمیان میں موجود ہو تو اس واسطے کی موجودگی میں وہ رشتہ دار محروم ہو جاتا ہے جیسا کہ باپ کی موجودگی میں دادا اور ماں کی موجودگی میں نانی، بیٹے کی موجودگی میں پوتے پوتیاں وغیرہ، لیکن اخیافی بہن بھائی اس اصول سے مستثنیٰ ہیں۔ وہ صرف ماں کے واسطے سے میت کے بہن بھائی ہوتے ہیں اور ماں کی موجودگی میں بھی وارث بنتے ہیں۔ اخیافی بہن بھائیوں کی دوسری خصوصیت یہ ہے ...... کہ ان کی وراثت میں مذکر و مؤنث میں کوئی فرق نہیں، بلکہ برابر کی وراثت پاتے ہیں۔ سورۂ نساء کے دوسرے رکوع میں انھیں کا تذکرہ ہے جبکہ باقی دو قسم کے بہن بھائیوں کی وراثت کا تذکرہ سورۂ نساء کی آخری آیت میں ہے۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا: أَنَّ الْإِخْوَةَ لِلْأُمِّ لَا يَرِثُونَ مَعَ الْوَلَدِ شَيْئاً، وَلَا مَعَ وَلَدِ الْأَبْنَاءِ - ذُكْرَاناً كَانُوا أَوْ إِنَاثاً - شَيْئاً وَلَا يَرِثُونَ مَعَ الْأَبِ، وَلَا مَعَ الْجَدِّ أَبِي الْأَبِ شَيْئاً، وَأَنَّهُمْ يَرِثُونَ فِيمَا سِوَى ذَلِكَ، يُفْرَضُ لِلْوَاحِدِ مِنْهُمُ السُّدُسُ - ذَكَراً كَانَ أَوْ أُنْثَى - فَإِنْ كَانَا اثْنَيْنِ، فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ، فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ يَقْتَسِمُونَهُ بَيْنَهُمْ بِالسَّوَاءِ، لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَى، وَذَلِكَ أَنَّ اللهَ تَبَارَكَ وَتَعَالَى يَقُولُ فِي كِتَابِهِ: ﴿وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ﴾ [النساء: ۱۲] فَكَانَ الذَّكَرُ وَالْأُنْثَى فِي هَذَا بِمَنْزِلَةٍ وَاحِدَةٍ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اجماع ہے کہ بے شک ماں کی طرف سے (اخیافی) بہن بھائی نہ تو (میت کی حقیقی) اولاد کی موجودگی میں وارث بنتے ہیں، نہ بیٹوں کی اولاد کے ساتھ وراثت میں کچھ پاتے ہیں، خواہ (یہ اخیافی بہن بھائی) مذکر ہوں یا مؤنث، نہ یہ باپ کے ساتھ کسی چیز کے وارث بن سکتے ہیں اور نہ ہی دادے کے ساتھ۔ اور بلاشبہ وہ ان (چار صورتوں) کے علاوہ میں وارث بنتے ہیں۔ ان میں سے صرف ایک (موجود) ہو خواہ مذکر ہو یا مؤنث تو اس کے لیے چھٹا حصہ ہے، اور اگر دو ہوں تو ان میں سے ہر ایک کے لیے چھٹا چھٹا حصہ ہے (جنھیں ملائیں تو کل مال کا تیسرا حصہ بنتا ہے) اور اگر وہ دو سے زیادہ ہوں تو (اس صورت میں بھی) وہ تیسرے حصے میں شریک ہوں گے (اور) اسے آپس میں برابر برابر بانٹ لیں گے۔ (ان بہن بھائیوں) میں مذکر کے لیے مؤنث کے حصے کے برابر ہے اور یہ اس وجہ سے ہے کہ بلاشبہ اللہ تبارک و تعالیٰ اپنی کتاب میں فرماتے ہیں:","﴿ وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ ﴾ [النساء: ۱۲]","’’اور اگر وہ آدمی جس کا ورثہ تقسیم کیا جا رہا ہو، اس کا بیٹا ہو نہ باپ یا ایسی ہی (فوت شدہ) عورت ہو اور اس (میت) کا ایک بھائی یا ایک بہن ہو تو ان دونوں میں سے ہر ایک کے لیے چھٹا حصہ ہے، پھر اگر ان کی تعداد اس سے زیادہ ہو تو وہ سب ایک تہائی حصے میں شریک ہوں گے۔‘‘","پس اس (اخیافی سلسلے کی وراثت) میں مذکر و مؤنث ایک ہی مرتبہ و مقام جیسے ہیں۔","...... ’’كَلَالَةٌ‘‘ کی تعریف یہ ہے: ’’مَا لَا أَصْلَ لَهُ وَلَا فَرْعَ‘‘ یعنی وہ شخص جس کی نہ کوئی اصل ہو اور نہ فرع، بالفاظ دیگر نہ تو اس کا باپ دادا یا پردادا میں سے کوئی زندہ ہو اور نہ حقیقی اولاد اور نہ بیٹوں یا پوتوں کی اولاد ہو۔"],"561":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کا ایک فتویٰ مذکور ہے جس میں انھوں نے چار باتیں بیان کی ہیں: (۱) بہن بھائی کن ورثاء کی موجودگی میں محروم ہوتے ہیں۔ (۲) صرف بیٹیوں یا پوتیوں کی موجودگی میں وہ عصبہ بن جاتے ہیں بشرطیکہ ورثاء میں دادا شامل نہ ہو۔ (۳) سورۂ نساء کی آخری آیت میں بیان کردہ بہن بھائیوں کی وراثت اور (۴) اخیافی بہن بھائیوں کے ساتھ شرکت۔","...... سگے بہن بھائیوں کی وراثت کا تذکرہ سورۂ نساء کی آخری آیت میں ہے، ان کو حقیقی، عینی بہن بھائی اور بنو الاب والام بھی کہتے ہیں۔ امام مالک رحمہ اللہ نے متن میں ان بہن بھائیوں کا جہاں بھی ذکر کیا ہے وہاں ’’لِلْأُمِّ وَالْأَبِ‘‘ کے الفاظ استعمال کیے ہیں، ہم اکثر طور پر تو ان کا لفظی ترجمہ ہی کریں گے لیکن کہیں کہیں ترجمہ و مفہوم کی آسانی کی خاطر ’’حقیقی‘‘ کا لفظ لکھیں گے۔ جس طرح کہ اخیافی بہن بھائیوں کے متعلق امام صاحب نے ’’لِلْأُمِّ‘‘ کا لفظ ذکر کیا ہے، ہم اس کا بھی کبھی لفظی ترجمہ کریں گے اور کبھی ’’اخیافی‘‘ کے لفظ سے ترجمہ کریں گے۔ کوئی وارث کسی دوسرے وارث کی وجہ سے بالکل محروم ہو جائے یا کم حصہ کی طرف منتقل ہو جائے تو اسے علم وراثت میں ’’حجب‘‘ کہتے ہیں، بالکل محرومی ہو تو اسے ’’حجب حرمان‘‘ کہتے ہیں اور یہ چھ افراد (خاوند، بیوی، ماں، باپ، بیٹا اور بیٹی) کے علاوہ ہر کسی میں ہو سکتا ہے اور اگر حصہ میں کمی واقع ہو تو اسے ’’حجب نقصان‘‘ کہتے ہیں اور یہ پانچ افراد میں ہوتا ہے: خاوند، بیوی، ماں، پوتی اور علاتی بہن۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا: أَنَّ الْإِخْوَةَ لِلْأَبِ وَالْأُمِّ لَا يَرِثُونَ مَعَ الْوَلَدِ الذَّكَرِ شَيْئاً، وَلَا مَعَ وَلَدِ الِابْنِ الذَّكَرِ شَيْئاً، وَلَا مَعَ الْأَبِ دِنْيَا شَيْئاً، وَهُمْ يَرِثُونَ مَعَ الْبَنَاتِ وَبَنَاتِ الْأَبْنَاءِ، مَا لَمْ يَتْرُكِ الْمُتَوَفَّى جَدًّا أَبَا أَبٍ، مَا فَضَلَ مِنَ الْمَالِ يَكُونُونَ فِيهِ عَصَبَةً، يُبْدَأُ بِمَنْ كَانَ لَهُ أَصْلُ فَرِيضَةٍ مُسَمَّاةٍ، فَيُعْطَوْنَ فَرَائِضَهُمْ، فَإِنْ فَضَلَ بَعْدَ ذَلِكَ فَضْلٌ، كَانَ لِلْإِخْوَةِ لِلْأَبِ وَالْأُمِّ يَقْتَسِمُونَهُ بَيْنَهُمْ، عَلَى كِتَابِ اللهِ -","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس حکم پر اتفاق ہے کہ (۱) بے شک ماں اور باپ دونوں کی طرف سے (میت کے) بہن بھائی نہ تو (میت کے) مذکر اولاد کے ساتھ (ان کی موجودگی میں) وارث بن سکتے ہیں اور نہ ہی (میت کے) بیٹے کی مذکر اولاد کی موجودگی میں کچھ پا سکتے ہیں، (اسی طرح) اور نہ ہی قریب والے باپ کے ساتھ (اس کی موجودگی میں) کچھ لے سکتے ہیں۔ (۲) وہ (حقیقی بہن بھائی) میت کی بیٹیوں اور پوتیوں کے ساتھ باقی ماندہ مال کے وارث بنتے ہیں، بشرطیکہ میت نے دادا نہ چھوڑا ہو، چنانچہ وہ اس میں عصبہ (شمار) ہوں گے۔ (وراثت کی تقسیم ذُكْرَاناً كَانُوا أَوْ إِنَاثاً - لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، فَإِنْ لَمْ يَفْضُلْ شَيْءٌ فَلَا شَيْءَ لَهُمْ. قَالَ: وَإِنْ لَمْ يَتْرُكِ الْمُتَوَفَّى أَباً، وَلَا جَدّاً أَبَا أَبٍ، وَلَا وَلَداً، وَلَا وَلَدَ ابْنٍ - ذَكَراً كَانَ أَوْ أُنْثَى - فَإِنَّهُ يُفْرَضُ لِلْأُخْتِ الْوَاحِدَةِ لِلْأَبِ وَالْأُمِّ النِّصْفُ، فَإِنْ كَانَتَا اثْنَتَيْنِ فَمَا فَوْقَ ذَلِكَ مِنَ الْأَخَوَاتِ لِلْأَبِ وَالْأُمِّ، فُرِضَ لَهُنَّ الثُّلُثَانِ، فَإِنْ كَانَ مَعَهُنَّ أَخٌ ذَكَرٌ، فَلَا فَرِيضَةَ لِأَحَدٍ مِنَ الْأَخَوَاتِ، وَاحِدَةً كَانَتْ أَوْ أَكْثَرَ مِنْ ذَلِكَ، وَيُبْدَأُ بِمَنْ شَرِكَهُمْ بِفَرِيضَةٍ مُسَمَّاةٍ، فَيُعْطَوْنَ فَرَائِضَهُمْ، فَمَا فَضَلَ بَعْدَ ذَلِكَ مِنْ شَيْءٍ، كَانَ بَيْنَ الْإِخْوَةِ لِلْأَبِ وَالْأُمِّ، لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، إِلَّا فِي فَرِيضَةٍ وَاحِدَةٍ فَقَطْ، لَمْ يَكُنْ لَهُمْ فِيهَا شَيْءٌ، فَاشْتَرَكُوا فِيهَا مَعَ بَنِي الْأُمِّ فِي ثُلُثِهِمْ، وَتِلْكَ الْفَرِيضَةُ هِيَ امْرَأَةٌ تُوُفِّيَتْ، وَتَرَكَتْ زَوْجَهَا وَأُمَّهَا، وَإِخْوَتَهَا لِأُمِّهَا، وَإِخْوَتَهَا لِأُمِّهَا وَأَبِيهَا، فَكَانَ لِزَوْجِهَا النِّصْفُ، وَلِأُمِّهَا السُّدُسُ، وَلِإِخْوَتِهَا لِأُمِّهَا الثُّلُثُ، فَلَمْ يَفْضُلْ شَيْءٌ بَعْدَ ذَلِكَ، فَيَشْتَرِكُ بَنُو الْأَبِ وَالْأُمِّ فِي هَذِهِ الْفَرِيضَةِ، مَعَ بَنِي الْأُمِّ فِي ثُلُثِهِمْ، فَيَكُونُ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَى، مِنْ أَجْلِ أَنَّهُمْ كُلُّهُمْ إِخْوَةُ الْمُتَوَفَّى لِأُمِّهِ، وَإِنَّمَا وَرِثُوا بِالْأُمِّ، وَذَلِكَ أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ فِي كِتَابِهِ:","﴿ وَإِنْ کا) آغاز ان ورثاء کے ساتھ کیا جائے گا جن کے لیے متعین و مقرر حصہ ہے، پس ان (اصحاب الفرائض) کو ان کے فرائض (مقرر حصے) دے دیے جائیں گے، پھر اگر اس کے بعد کچھ زائد مال بچ جائے تو وہ ان حقیقی بہن بھائیوں کے لیے ہوگا، جسے وہ کتاب اللہ کے مطابق آپس میں تقسیم کرلیں گے، خواہ مذکر ہوں یا مؤنث، اور ہر مذکر (بھائی) کے لیے دو مؤنثوں (بہنوں) کے برابر (حصہ) ہوگا، اور اگر کچھ بھی نہ بچے تو انھیں کچھ نہ ملے گا (اور اگر میت کا دادا بھی موجود ہو تو امام مالک رحمہ اللہ کے نزدیک اس صورت میں بہن بھائی وارث تو بنیں گے لیکن وہ اکیلے باقی ماندہ مال کے حق دار نہ ہوں گے بلکہ دادا بھی ان کے ساتھ شامل ہوگا، جس کی تفصیل آگے باب ۷ میں آرہی ہے۔) (۳) اگر میت نے (ورثاء میں) نہ باپ چھوڑا ہو، نہ دادا، نہ اولاد اور نہ بیٹے کی اولاد، نہ مذکر نہ مؤنث (یعنی میت کلالہ ہو، البتہ بہن بھائی ہوں، چنانچہ اگر صرف ایک حقیقی بہن وارث بن رہی ہو تو بلا شبہ ماں باپ کی طرف سے ایک (حقیقی اور سگی) بہن کے لیے نصف حصہ فرض (اور مقرر) ہے، اور اگر وہ دو یا اس سے زیادہ حقیقی بہنیں (وارث بن رہی) ہوں تو انھیں فرض (مقرر شدہ) حصہ دو تہائی دیا جائے گا اور اگر ان (بہنوں) کے ساتھ کوئی لڑکا یعنی بھائی موجود ہو تو پھر بہنوں میں سے کسی کے لیے کوئی فرض و مقرر حصہ نہ ہوگا، خواہ ایک بہن ہو یا اس سے زیادہ ہوں (بلکہ بھائی کے ساتھ مل کر وہ عصبہ بن جائیں گی) اور ان ورثاء کے ساتھ (تقسیم وراثت کی) ابتدا کی جائے گی جو ان (بہن بھائیوں) کے ہمراہ اپنے مقرر حصوں کے ساتھ شریک ہوں، چنانچہ كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ ﴾ [النساء: ۱۲]","فَلِذَلِكَ شُرِّكُوا فِي هَذِهِ الْفَرِيضَةِ، لِأَنَّهُمْ كُلُّهُمْ إِخْوَةُ الْمُتَوَفَّى لِأُمِّهِ.","انھیں ان کے فرض و مقرر حصے دے دیے جائیں گے، پھر اس کے بعد جو کچھ بھی زائد بچ جائے وہ حقیقی بہن بھائیوں کے لیے (اس اصول کے تحت) ہوگا کہ ہر مذکر کے لیے دو مؤنثوں کے برابر حصہ ہے۔ (۴) سوائے صرف ایک مسئلے کے، کہ اس میں ان کے لیے (عصبہ ہونے کے باوجود) کچھ (مخصوص) نہ ہوگا بلکہ وہ اس مسئلے میں اخیافی بہن بھائیوں کے ہمراہ ان کے تہائی حصے میں شریک ہوں گے۔ اور وہ مسئلہ یہ ہے کہ ایک عورت فوت ہو جائے اور (ورثاء میں) اپنا خاوند، ماں، ماں کی طرف سے ایک سے زیادہ (اخیافی) بہن بھائی اور ماں باپ دونوں کی طرف سے (حقیقی) بہن بھائی چھوڑ جائے۔ چنانچہ خاوند کے لیے نصف ہوگا، اس کی ماں کے لیے سدس (چھٹا حصہ) ہوگا، ماں کی طرف سے بہن بھائیوں کے لیے ثلث (تہائی مال) ہوگا (اور حقیقی بہن بھائی اصول کے مطابق تو عصبہ بنیں گے، اور یہ مسئلہ چھ پر حل ہوگا یعنی کل مال کے چھ حصے کریں گے، جن میں سے خاوند کو (نصف یعنی) تین مل جائیں گے، ماں کو (چھٹا حصہ یعنی) ایک ملے گا اور بہن بھائیوں کو (تہائی مال یعنی) دو حصے مل جائیں گے، اس طرح چھ حصے پورے پورے تقسیم ہو جائیں گے، اور حقیقی بہن بھائی عصبہ بن رہے ہیں اور عصبہ کو باقی ماندہ مال ملنا ہوتا ہے لیکن یہاں تو اس تقسیم کے بعد کچھ بھی زائد نہیں بچا، لہذا باپ اور ماں کی طرف سے (حقیقی) بہن بھائی اس مسئلے میں صرف ماں کی طرف سے (اخیافی) بہن بھائیوں کے ساتھ ان کے ثلث (تہائی مال) میں شریک ہو جائیں گے اور (اس صورت میں) ہر مذکر کے لیے ایک مؤنث کے حصے کے برابر ہوگا، اس وجہ سے کہ وہ سب کے سب میت کی ماں کی طرف سے بہن بھائی (کی حیثیت میں شریک ہو رہے ہیں اور وہ ماں کی وجہ سے وارث بن رہے ہیں اور یہ (مذکر و مؤنث کے حصوں کی برابری) اس وجہ سے ہے کہ یقیناً اللہ تبارک و تعالیٰ نے فرمایا:","﴿ وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ ﴾ [النساء: ۱۲]","’’اور اگر وہ آدمی جس کا ورثہ تقسیم کیا جا رہا ہو، اس کا بیٹا ہو نہ باپ یا ایسی ہی عورت ہو اور اس کا ایک بھائی یا ایک بہن ہو تو ان دونوں میں سے ہر ایک کے لیے چھٹا حصہ ہے، پھر اگر ان کی تعداد اس سے زیادہ ہو تو وہ سب ایک تہائی حصے میں شریک ہوں گے۔‘‘","سو (بہر حال) وہ اسی وجہ سے اس مسئلے میں شریک کیے گئے ہیں کیونکہ وہ سب کے سب میت کی ماں کی طرف سے بھائی (بہن ہونے میں شریک) ہیں۔","...... اگرچہ حقیقی بہن بھائیوں کا میت کے ساتھ باپ کی طرف سے بھی رشتہ ہے لیکن یہاں اس کا اعتبار نہیں کیا گیا، کیونکہ اس کا اعتبار کرنے سے انھیں اصحاب الفرائض کی بجائے عصبات میں شامل کرنا پڑے گا جنھیں باقی ماندہ مال ملا کرتا ہے اور مذکورہ مسئلے میں کچھ باقی بچتا ہی نہیں ہے، اور یہ مناسب نہیں کہ جن بہن بھائیوں کا ماں کے ساتھ اکہرا رشتہ ہو یعنی صرف ماں کی طرف سے میت کے بہن بھائی ہوں انھیں تو وراثت میں سے حصہ ملے اور جن بہن بھائیوں کا میت سے دوہرا رشتہ ہو یعنی سگے بہن بھائی ہوں وہ محروم رہیں، باپ کی طرف سے رشتہ داری اگر فائدہ نہیں دے رہی تو اسے نقصان بھی نہ دینا چاہیے۔ لہذا یہاں ان حقیقی بہن بھائیوں کو اخیافی بہن بھائیوں کی حیثیت میں شمار کرلیا جائے گا جن میں مذکر و مؤنث کو برابر برابر حصہ ملتا ہے۔ یہ مسئلہ علم میراث کی اصطلاح میں ’’مسئلہ مشرکہ‘‘ کہلاتا ہے، نیز اسے مشترکہ، حماریہ، حجریہ اور عمریہ بھی کہتے ہیں۔ سیدنا عمر، سیدنا عثمان، سیدنا ابن عباس، سیدنا ابن مسعود اور سیدنا زید بن ثابت اور سیدہ عائشہ رضی اللہ عنہم کا یہی موقف ہے، نیز امام مالک رحمہ اللہ اور امام شافعی رحمہ اللہ بھی اسی کے قائل ہیں جبکہ امام ابو حنیفہ رحمہ اللہ اور امام احمد رحمہ اللہ کے نزدیک مذکورہ صورت میں حقیقی بہن بھائی اخیافیوں کے ساتھ شریک نہ ہوں گے اور محروم ہی رہیں گے اور یہی موقف سیدنا علی اور سیدنا ابو موسیٰ اشعری رضی اللہ عنہم سے منقول ہے اور سیدنا ابن عباس اور سیدنا ابن مسعود رضی اللہ عنہم کی طرف بھی منسوب ہے، یہی راجح ہے، تا کہ ورثاء کی مختلف اقسام کا ایک ہونا لازم نہ آئے نیز آیات کا ظاہری مفہوم بھی یہی ہے۔"],"562":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کا ایک فتویٰ مذکور ہے جس میں انھوں نے تین مسائل ذکر کیے ہیں: (۱) حقیقی بہن بھائیوں کی عدم موجودگی میں علاتی بہن بھائیوں کی حیثیت حقیقی بہن بھائیوں ہی کی طرح ہے سوائے ’’مسئلہ مشترکہ‘‘ کے جس کا گزشتہ باب میں تذکرہ ہوا ہے۔ (۲) اگر حقیقی اور علاتی بہن بھائی جمع ہو جائیں تو تین صورتیں بنتی ہیں (الف) حقیقی بھائی کی موجودگی میں سب علاتی بہن بھائی محروم ہوں گے۔ (ب) ایک حقیقی بہن کی موجودگی میں علاتی بہنوں کو چھٹا حصہ ملے گا اگر علاتی بھائی نہ ہو، اور اگر علاتی بھائی ہو تو سب علاتی بہن بھائی عصبہ ہوں گے۔ (ج) دو حقیقی بہنوں کی موجودگی میں علاتی بہنیں محروم ہوتی ہیں الا یہ کہ ان کے ساتھ علاتی بھائی ہو تو پھر وہ عصبہ بن جائیں گے۔ (۳) اخیافی بہن بھائیوں کی وراثت پر نہ حقیقی بہن بھائی اثر انداز ہوتے ہیں اور نہ علاتی۔","...... میت کے باپ کی طرف سے بہن بھائیوں کو علاتی، پدری، بَنُو الْأَبِ یا بَنُو الْعَلَّاتِ بھی کہتے ہیں۔ جن کی وراثت کا معاملہ زیادہ تر حقیقی بہن بھائیوں جیسا ہی ہے اور جن ورثاء کی وجہ سے حقیقی بہن بھائی محروم ہو جاتے ہیں ان کی وجہ سے علاتی بہن بھائیوں کو بھی محروم ہونا پڑتا ہے۔ البتہ چند ایک مزید مسائل اور فرق یہاں مذکور ہیں۔ ان دونوں قسم کے بہن بھائیوں کا کچھ معاملہ پہلے باب میں مذکور آخری صورت کی طرح بھی ہے کہ میت کی حقیقی اولاد بیٹے بیٹیاں اور میت کے پوتے پوتیاں جمع ہو جائیں تو جو صورتیں ان کی بنتی ہیں وہی یہاں بھی بنتی ہیں ...... امام صاحب نے متن میں علاتی بہن بھائیوں کے لیے ’’للأب‘‘ یا ’’بنی الاب‘‘ کے الفاظ استعمال کیے ہیں، ہم کبھی تو ان کا لفظی ترجمہ کریں گے اور کبھی مفہوم میں آسانی کے لیے ترجمے میں ’’علاتی‘‘ کا لفظ استعمال کریں گے۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا، أَنَّ مِيرَاثَ الْإِخْوَةِ لِلْأَبِ، إِذَا لَمْ يَكُنْ مَعَهُمْ أَحَدٌ مِنْ بَنِي الْأَبِ وَالْأُمِّ، كَمَنْزِلَةِ الْإِخْوَةِ لِلْأَبِ وَالْأُمِّ سَوَاءٌ، ذَكَرُهُمْ كَذَكَرِهِمْ، وَأُنْثَاهُمْ كَأُنْثَاهُمْ، إِلَّا أَنَّهُمْ لَا يُشَرَّكُونَ مَعَ بَنِي الْأُمِّ فِي الْفَرِيضَةِ، الَّتِي شَرَّكَهُمْ فِيهَا بَنُو الْأَبِ وَالْأُمِّ، لِأَنَّهُمْ خَرَجُوا مِنْ وِلَادَةِ الْأُمِّ الَّتِي جَمَعَتْ أُولَئِكَ. قَالَ مَالِكٌ: فَإِنِ اجْتَمَعَ الْإِخْوَةُ لِلْأَبِ وَالْأُمِّ، وَالْإِخْوَةُ لِلْأَبِ، فَكَانَ فِي بَنِي الْأَبِ وَالْأُمِّ ذَكَرٌ، فَلَا مِيرَاثَ لِأَحَدٍ مِنْ بَنِي الْأَبِ، وَإِنْ لَمْ يَكُنْ بَنُو الْأَبِ وَالْأُمِّ إِلَّا امْرَأَةً وَاحِدَةً، أَوْ أَكْثَرَ مِنْ ذَلِكَ مِنَ الْإِنَاثِ لَا ذَكَرَ مَعَهُنَّ، فَإِنَّهُ يُفْرَضُ لِلْأُخْتِ الْوَاحِدَةِ لِلْأَبِ وَالْأُمِّ النِّصْفُ، وَيُفْرَضُ لِلْأَخَوَاتِ لِلْأَبِ السُّدُسُ تَتِمَّةَ الثُّلُثَيْنِ، فَإِنْ كَانَ مَعَ الْأَخَوَاتِ لِلْأَبِ ذَكَرٌ، فَلَا فَرِيضَةَ لَهُنَّ، وَيُبْدَأُ بِأَهْلِ الْفَرَائِضِ الْمُسَمَّاةِ فَيُعْطَوْنَ فَرَائِضَهُمْ، فَإِنْ فَضَلَ بَعْدَ ذَلِكَ فَضْلٌ كَانَ بَيْنَ الْإِخْوَةِ لِلْأَبِ، لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، وَإِنْ لَمْ يَفْضُلْ شَيْءٌ فَلَا شَيْءَ لَهُمْ، فَإِنْ كَانَ الْإِخْوَةُ لِلْأَبِ وَالْأُمِّ امْرَأَتَيْنِ أَوْ أَكْثَرَ مِنْ ذَلِكَ مِنَ الْإِنَاثِ، فُرِضَ لَهُنَّ الثُّلُثَانِ، وَلَا","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں یہ حکم اجماعی ہے کہ (۱) بے شک باپ کی طرف سے بہن بھائیوں (یعنی علاتی بہن بھائیوں) کے ساتھ جب ماں باپ دونوں کی طرف سے بہن بھائیوں (یعنی حقیقی بہن بھائیوں) میں سے کوئی بھی نہ ہو تو ان کی وراثت حقیقی بہن بھائیوں ہی کی طرح (بالکل ان کے) برابر برابر ہوتی ہے، ان (علاتیوں) میں سے مذکر ان (حقیقیوں) کے مذکر کی طرح اور ان میں سے مؤنث ان کی مؤنث کی طرح ہے (یعنی اکیلا علاتی بھائی ہو تو کل مال کا وارث بنے گا، اکیلی علاتی بہن ہو تو نصف لے گی، دو یا زیادہ علاتی بہنیں ہوں تو دو تہائی لیں گی اور اگر بہن بھائی اکٹھے ہوں تو ہر بھائی کو دو بہنوں کے برابر ملے گا، البتہ یہ فرق ہے کہ) مگر بلاشبہ یہ (علاتی بہن بھائی) ماں کی طرف سے بہن بھائیوں (یعنی اخیافی بہن بھائیوں) کے ساتھ اس مسئلے (مسئلہ مشترکہ) میں شریک نہ ہوں گے جس میں ماں باپ دونوں کی طرف سے بہن بھائیوں (یعنی حقیقی بہن بھائیوں) کو ان (اخیافیوں) کے ساتھ شریک کیا گیا تھا، کیونکہ بے شک وہ (حقیقی و اخیافی تو) ایک ہی ماں سے پیدا ہوئے تھے (اور) اس ماں نے ان سب کو (رشتہ داری میں) اکٹھا کیا تھا۔ (یعنی جس طرح اخیافی بہن بھائی میت کے ساتھ اس ماں کی وجہ سے بہن بھائی کا رشتہ رکھتے ہیں، اسی طرح حقیقی بہن بھائیوں کی میت کے ساتھ رشتہ داری میں بھی یہ ماں شامل ہے، لیکن علاتی یعنی پدری بھائیوں کا میت سے یہ تعلق نہیں ہے کیونکہ میت کی ماں اور ہے اور مِيرَاثَ مَعَهُنَّ لِلْأَخَوَاتِ لِلْأَبِ، إِلَّا أَنْ يَكُونَ مَعَهُنَّ أَخٌ لِأَبٍ، فَإِنْ كَانَ مَعَهُنَّ أَخٌ لِأَبٍ بُدِئَ بِمَنْ شَرَّكَهُمْ بِفَرِيضَةٍ مُسَمَّاةٍ، فَأُعْطُوا فَرَائِضَهُمْ، فَإِنْ فَضَلَ بَعْدَ ذَلِكَ فَضْلٌ، كَانَ بَيْنَ الْإِخْوَةِ لِلْأَبِ، لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ، وَإِنْ لَمْ يَفْضُلْ شَيْءٌ فَلَا شَيْءَ لَهُمْ، وَلِبَنِي الْأُمِّ مَعَ بَنِي الْأَبِ وَالْأُمِّ، وَمَعَ بَنِي الْأَبِ، لِلْوَاحِدِ السُّدُسُ، وَلِلاثْنَيْنِ فَصَاعِداً الثُّلُثُ، لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَى، هُمْ فِيهِ بِمَنْزِلَةٍ وَاحِدَةٍ سَوَاءٌ.","پدری بہن بھائیوں کی ماں اور ہے)۔ (۲) پھر اگر ماں باپ دونوں کی طرف سے بہن بھائی اور صرف باپ کی طرف سے بہن بھائی جمع ہو جائیں (حقیقی اور علاتی اکٹھے ہو جائیں) (الف) اور حقیقی بہن بھائیوں میں کوئی مذکر موجود ہو تو علاتی بہن بھائیوں میں سے کسی کے لیے بھی کچھ نہ ہوگا (ب) اور اگر حقیقی بہن بھائیوں میں صرف ایک عورت یا اس سے زیادہ عورتوں (حقیقی بہنوں) کے سوا کوئی نہ ہو (یعنی) ان کے ساتھ کوئی مذکر (حقیقی بھائی) نہ ہو (تو پھر علاتی بہن بھائیوں کو کچھ مل سکتا ہے۔ جس کی تفصیل یہ ہے کہ اگر صرف ایک حقیقی بہن ہو) تو بلا شبہ ماں باپ دونوں کی طرف سے (میت کی حقیقی) ایک بہن کو اس کا فرض (مقرر) حصہ نصف دیا جائے گا اور (ایک یا زیادہ) علاتی بہنوں کے لیے سدس یعنی چھٹا حصہ ہوگا، ثلثان (دوتہائی) کو پورا کرنے کے لیے (ایسا کیا جائے گا، جس طرح کہ ایک بیٹی کے ساتھ پوتی کا معاملہ ہوتا ہے، چنانچہ یہاں میت کی بہنوں کی دو حیثیتیں ہیں، حقیقی بہن صرف ایک ہے جو نصف کی حقدار ہے لیکن مجموعی طور پر ایک سے زیادہ بہنیں ہیں جنھیں دو تہائی مال ملتا ہے۔ چنانچہ اب علاتی بہن یا بہنوں کو اتنا مال دیا جائے گا کہ جب اسے حقیقی بہن کے نصف کے ساتھ جمع کریں تو دونوں کا مجموعہ ثلثان (دوتہائی) ہو جائے۔ لہذا علاتی بہن کو سدس یعنی چھٹا حصہ دیں گے، کیونکہ نصف اور سدس کا مجموعہ ثلثان ہے، مثلاً: مال کے کل چھ حصوں میں سے دو تہائی کی مقدار چار حصے بنتی ہے جن میں سے تین حصے حقیقی بہن کو مل چکے تھے اور باقی ایک حصہ علاتی بہنوں کو مل جائے گا اور یہ ایک حصہ کل مال کا سدس یعنی چھٹا ہے)، پھر اگر (مذکورہ صورت میں کہ جب حقیقی بہن ایک ہو اور نصف مال لے جائے اور) ان علاتی بہنوں کے ساتھ کوئی مذکر (یعنی علاتی بھائی) ہو تو ان کے لیے کوئی مقرر فرضی حصہ نہ ہوگا بلکہ وہ اپنے بھائیوں کے ساتھ مل کر عصبہ بن جائیں گی) اور ان ورثاء سے (تقسیم وراثت کے لیے) ابتدا کی جائے گی جو متعین فرضی حصوں والے ہیں (یعنی اصحاب الفرائض ہیں۔ چنانچہ انھیں ان کے فرضی حصے دے دیے جائیں گے، پھر اس کے بعد اگر کچھ بچ جائے تو وہ علاقی بہن بھائیوں کے درمیان ’’لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ‘‘ کے مطابق تقسیم ہو گا یعنی ہر مذکر کے لیے دو مؤنثوں کے برابر ہوگا اور اگر کچھ بھی زائد مال نہ بچے تو ان سب کے لیے کچھ بھی نہ ہوگا۔ (ج) اگر حقیقی بہن بھائیوں میں دو عورتیں یا ان سے زیادہ عورتیں (حقیقی بہنیں) ہوں تو انھیں کو فرضی حصہ ثلثان (دوتہائی) دے دیا جائے گا اور ان کی موجودگی میں علاتی بہنوں کے لیے کچھ بھی وراثت نہ ہوگی، الا یہ کہ ان کے ہمراہ کوئی علاتی بھائی موجود ہو تو پھر وہ بھائی کی وجہ سے عصبہ بن کر باقی ماندہ لے سکتی ہیں)۔ چنانچہ اگر ان (علاتی بہنوں) کے ساتھ علاتی بھائی ہو تو ان لوگوں کو متعین فرضی حصوں کے ساتھ (وراثت کی تقسیم کا) آغاز کیا جائے گا جو ان کے ساتھ شریک ہیں (سب سے پہلے اصحاب الفرائض کو ملے گا)، انھیں ان کے فرض (مقرر) حصے دے دیے جائیں گے، پھر اس کے بعد اگر کچھ زائد بچ جائے تو وہ (تمام) علاتی بہن بھائیوں کے مابین اس طرح تقسیم ہوگا کہ ہر مذکر کے لیے دو مؤنثوں کے برابر حصہ ہوگا، اور اگر کچھ بھی زائد نہ بچے تو ان کے لیے کچھ بھی (حق) نہ ہوگا۔ (۳) اور بنو الام یعنی اخیافی بہن بھائیوں کے لیے حقیقی بہن بھائیوں کی موجودگی میں بھی اور علاتی بہن بھائیوں کے ساتھ بھی ضرور حصہ نکالا جائے گا، اس طرح کہ ایک کے لیے سدس (چھٹا حصہ) ہوگا اور دو یا اس سے زیادہ کے لیے ثلث (تہائی) ہوگا، اس طرح کہ ہر مذکر کے لیے ایک مؤنث کے برابر حصہ ہوگا۔ پس وہ اس (تقسیم) میں ایک ہی طرح اور برابر برابر ہیں۔","یعنی اگرچہ اخیافی بہن بھائیوں کا میت کے ساتھ رشتہ نسبتاً کمزور ہے لیکن ان کا حصہ اللہ نے پکا کر دیا ہے، حقیقی اور علاتی بہن بھائیوں پر ان کی وجہ سے تو اثر پڑ سکتا ہے کہ یہ مقرر حصہ لے جائیں اور حقیقی و علاتی محروم رہ جائیں لیکن الٹ نہیں ہوسکتا۔"],"563":["§خلاصۃ الباب","اس باب میں تین موقوف روایات (آثار صحابہ رضی اللہ عنہم) ہیں جن میں سے ایک ضعیف اور دو صحیح ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","جد عربی زبان میں دادا، نانا، پڑدادا، پڑنانا وغیرہ سب پر بولا جاتا ہے، چونکہ نانا اصحاب الفرائض میں شامل ہے اور نہ عصبات میں اس لیے یہاں صرف باپ کا باپ یعنی دادا یا پڑدادا وغیرہ ہی مراد ہیں۔ اسے جد صحیح کہتے ہیں، یعنی ہر وہ جد جس کی نسبت میت کی طرف عورت کے واسطے سے نہ ہو۔ چنانچہ اگر میت اور کسی جد کے درمیان میں عورت کا واسطہ ہو جیسے کہ نانا (ماں کا باپ) یا دادی کا باپ وغیرہ تو اسے جد فاسد کہتے ہیں...... دادے کی وراثت کی تفصیل کچھ یوں ہے کہ باپ کی موجودگی میں دادے کو کچھ نہیں ملتا۔ باپ نہ ہو تو دادے کو باپ ہی کی طرح وراثت ملتی ہے یعنی میت کی مذکر اولاد ہو تو دادے کو صرف چھٹا حصہ ملے گا، میت کی صرف مؤنث اولاد ہو تو دادے کو پہلے چھٹا حصہ دیں گے، پھر عصبہ کے طور پر اسے باقی ماندہ مال بھی ملے گا اور اگر میت کی کوئی بھی اولاد نہ ہو تو راجح موقف کے مطابق دادا ہی عصبہ بنے گا...... دادے کے حوالے سے اہم اختلافی مسئلہ یہ ہے کہ دادے کی موجودگی میں بہن بھائی وارث بنتے ہیں یا نہیں۔ چنانچہ امام ابوحنیفہ رحمہ اللہ، ابن تیمیہ رحمہ اللہ، ابن قیم رحمہ اللہ، محمد بن عبدالوہاب رحمہ اللہ اور اہلحدیث کے نزدیک دادے کی موجودگی میں بہن بھائی اس طرح محروم رہتے ہیں جس طرح کہ باپ کی موجودگی میں انھیں کچھ نہیں ملتا۔ امام بخاری رحمہ اللہ کا بھی اسی طرف میلان ہے۔ (بخاری، قبل از حدیث: ۶۷۳۷) اکثر صحابہ کرام رضی اللہ عنہم کا یہی موقف تھا، جن میں حضرت ابوبکر، ابن عباس، ابن عمر، ابن زبیر، ابی بن کعب، حذیفہ بن یمان، ابوسعید خدری، معاذ بن جبل، ابو درداء، عمران بن حصین، جابر بن عبد اللہ، ابو موسیٰ اشعری اور سیدہ عائشہ صدیقہ رضی اللہ عنہا شامل ہیں۔ جبکہ امام مالک رحمہ اللہ، امام شافعی رحمہ اللہ اور امام احمد رحمہ اللہ کے نزدیک دادا کی موجودگی میں بہن بھائی بھی وارث بنتے ہیں۔ یہ موقف سیدنا عمر، عثمان، علی، ابن مسعود اور زید بن ثابت رضی اللہ عنہم سے منقول ہے۔ (نوٹ) اس باب میں امام مالک رحمہ اللہ کے بیان کردہ مسائل ان کے قول کے مطابق ہیں۔ اہل حدیث اور احناف کے ہاں ان سب میں دادے کی موجودگی میں بہن بھائی سرے سے محروم رہتے ہیں۔"],"564":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک مرفوع (حدیث نبوی صلی اللہ علیہ وسلم) ہے جو سنداً ضعیف ہے اور دو موقوف (آثار صحابہ رضی اللہ عنہم) ہیں جو کہ ضعیف ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","جدہ عربی زبان میں ہر قسم کی دادی، نانی، پڑدادی، پڑنانی وغیرہ سب پر بولا جاتا ہے۔ علم وراثت میں وراثت کی حقدار جدہ کو جدہ صحیحہ کہتے ہیں اور اس سے مراد ہر وہ جدہ ہے کہ جس کی میت کے ساتھ قرابت میں جد فاسد کا واسطہ نہ ہو، اگر جد فاسد کا واسطہ ہو تو جدہ بھی فاسدہ ہی کہلائے گی۔ سیدنا ابن مسعود رضی اللہ عنہ کے نزدیک جدہ وارث ہی نہیں بنتی لیکن باقی تمام امت کا اجماع ہے کہ جدہ وارث بن سکتی ہے۔ جدہ صحیحہ کی بہت ساری اقسام ہیں، مثلاً: باپ کی ماں (دادی) پھر باپ کی طرف سے دادے یا دادی کی مائیں (پڑدادیاں) اسی طرح ان میں سے ہر ایک کے باپ کی اور ماں کی مائیں، دوسری جانب ماں کی ماں (نانی)، پھر نانے یا نانی کی ماں (پڑنانی) اور اسی طرح آگے تک۔ جس طرح باپ نہ ہو تو اس کا حصہ باپ کے باپ کو مل جاتا ہے۔ اسی طرح ماں نہ ہو تو اس کا حصہ ماں کی ماں کو مل جاتا ہے، یہ بات تو متفقہ تھی۔ پھر اس بات میں اشکال پڑتا تھا کہ نانی کو اگر حصہ ملتا ہے تو کیا دادی کو بھی کچھ ملے گا یا نہیں؟ تو اس پر صحابہ کرام رضی اللہ عنہم کا اجماع ہے کہ اسے بھی ملے گا۔ دادی یا نانی یا پھر ان سے اوپر والی دادیاں یا نانیاں صرف اس صورت میں وارث بنیں گی جب ان کے درمیان اور میت کے درمیان میں واسطہ زندہ نہ ہو۔ چنانچہ باپ موجود ہو تو دادی اور پڑدادیاں محروم رہیں گی اور اگر ماں زندہ ہو تو نانی اور پڑنانیاں محروم رہیں گی، ہاں ماں زندہ ہو تو دادی بھی اور پڑدادیاں بھی محروم رہیں گی۔ اگرچہ وہ سب میت کی دوسری جانب سے ہیں لیکن وہ محروم اس لیے ہوں گی کہ دادیوں اور نانیوں کی وراثت ثابت ہی ماں کے نہ ہونے سے ہوتی ہے اور ماں والا چھٹا حصہ ہی ان تک پہنچتا ہے، تو جب ماں خود اپنا حصہ لینے کے لیے موجود ہوگی تو اوپر والی سب مائیں محروم رہیں گی۔ پھر یاد رہے کہ ماں کے حصے تو مختلف ہوتے ہیں، وہ کبھی چھٹا حصہ لیتی ہے اور کبھی تہائی مال، لیکن ماں کے نہ ہونے کی صورت میں دادیوں اور نانیوں کو صرف اور صرف چھٹا حصہ ہی ملتا ہے۔ تمام زندہ دادیوں اور نانیوں کو دیکھا جائے گا، پھر ان میں سے جو میت کے زیادہ قریب ہوگی وہ چھٹا حصہ لے گی اور اگر ایک سے زیادہ ہوں تو اسی چھٹے حصے کو باہم تقسیم کریں گی بشرطیکہ وہ سب میت سے دوری میں ایک ہی درجے میں برابر ہوں یعنی ان کے اور میت کے درمیان میں ایک ایک واسطہ ہو یا دو دو ہوں یا اس سے زیادہ واسطے ہوں لیکن برابر ہوں۔"],"565":["§خلاصۃ الباب","اس باب میں ایک مرفوع روایت یعنی حدیث نبوی صلی اللہ علیہ وسلم ہے جو کہ مسلم شریف میں بھی موجود ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","’’کلالہ‘‘ سے مراد وہ میت ہے کہ (مَنْ لَا أَصْلَ لَهُ وَلَا فَرْعَ) جس کی نہ کوئی اصل ہو اور نہ فرع یعنی نہ باپ، دادا، پڑدادا ہو اور نہ بیٹا، پوتا، پڑپوتا وغیرہ۔ جمہور علماء وفقہاء اور محدثین کا یہی قول ہے۔ بعض نے صرف اولاد کو کلالہ کہا ہے، بعض کے نزدیک ’’کلالہ‘‘ سے مراد ایسا وارث ہے جو نہ والد ہو نہ اولاد۔ لیکن پہلا قول ہی درست ہے۔"],"566":["§خلاصۃ الباب","اس باب میں دو موقوف روایات (آثار صحابہ رضی اللہ عنہم) ہیں اور دونوں ہی سنداً ضعیف ہیں۔","پھوپھی مرنے والے کے باپ کی بہن ہوتی ہے اور میت اگر مذکر ہے تو وہ اس پھوپھی کا بھتیجا ہوگی، چنانچہ اگر بھتیجا فوت ہو تو وہ کچھ بھی وراثت نہ لے گی کیونکہ اللہ تعالیٰ نے اسے نہ اصحاب الفرائض (جن کے حصے قرآن و حدیث میں مقرر ہیں) میں شامل فرمایا ہے اور نہ ہی یہ حدیث کی رو سے عصبات (جو اصحاب الفرائض سے بچا ہوا مال لیتے ہیں) میں داخل ہے کیونکہ یہ مؤنث ہے اور عصبہ مذکر ہوتا ہے۔ لہذا یہ ذوالارحام میں سے ہے، جن کو بھی وراثت ملتی ہے جب نہ اصحاب الفرائض ہوں اور نہ عصبات۔ ہاں اگر پھوپھی فوت ہو تو بھتیجا عصبہ کے طور پر اس کا وارث بن سکتا ہے۔"],"567":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے تین فتاویٰ جات مذکور ہیں۔","جن ورثاء کے حصے قرآن وسنت میں مقرر ہیں انھیں اصحاب الفرائض کہتے ہیں اور وہ ورثاء جو اصحاب الفرائض کی موجودگی میں ان کا باقی ماندہ اور ان کی عدم موجودگی میں سارا مال لیتے ہیں انھیں عصبہ کہتے ہیں جس کی جمع عصبات ہے۔ عصبہ کا لفظ خود بھی واحد، تثنیہ اور جمع سب کے لیے استعمال ہوتا رہتا ہے۔ یہ عصبات بھی مختلف اقسام پر مشتمل ہیں اور ان کی چار اہم قسمیں ہیں جن میں سے تین کا تعلق نسب سے ہے: (۱) عصبہ بالنفس (بذات خود عصبہ بننے والے، (۲) عصبہ بالغیر (وہ بہن جو بھائی کے ساتھ مل کر عصبہ بنے) اور (۳) عصبہ مع الغیر (وہ حقیقی یا علاتی بہن جو بیٹی یا پوتی سے بچا ہوا مال لے)۔ چوتھی قسم عصبہ سبی کی ہے یعنی جو آزادی کے سبب سے عصبہ بنتا ہے اور اپنے آزاد کیے ہوئے غلام کی وراثت پاتا ہے۔ اس باب میں عصبہ بالنفس (عصبہ بنفسہ) کی بحث ہے جو کہ صرف مذکر افراد ہوا کرتے ہیں۔ ان کے علاوہ باقی تمام قسم کے عصبات میں یا تو صرف عورتیں ہی ہوتی ہیں یا مرد وعورت شامل ہو سکتے ہیں۔ چنانچہ (عصبہ بنفسہ) سے مراد وہ مذکر رشتہ دار ہے کہ اس کے اور میت کے درمیان میں کسی عورت کا واسطہ نہ ہو، اس کی چار شاخیں ہیں اور بالترتیب وارث بنتی ہیں: (۱) ’’بُنُوَّۃ‘‘ یعنی بیٹا، وہ نہ ہو تو پوتا، وہ نہ ہو تو پڑپوتا اور اسی طرح نیچے تک۔ (۲) ’’أُبُوَّۃ‘‘ یعنی باپ، وہ نہ ہو تو دادا، پھر پڑدادا اور اسی طرح اوپر تک۔۔۔۔۔ یادر ہے کہ باپ دادا اصحاب الفرائض میں بھی شامل ہیں اور اگر میت کا بیٹا، پوتا وغیرہ نہ ہو تو پھر عصبہ بننے میں انھی کا درجہ ہے۔ یہ مسئلہ چونکہ واضح تھا اس لیے امام مالک رحمہ اللہ نے ان کی وضاحت نہیں فرمائی، بلکہ آگے آنے والی دونوں قسموں پر تفصیل اور مثالوں سے روشنی ڈالی ہے۔ (۳) ’’أُخُوَّۃ‘‘ یعنی حقیقی (سگا) بھائی، وہ نہ ہو تو علاتی بھائی، وہ نہ ہو تو حقیقی بھائی کا بیٹا، وہ نہ ہو تو علاتی بھائی کا بیٹا، اسی طرح پوتا وغیرہ نیچے تک۔ (۴) ’’عُمُومَۃ‘‘ یعنی میت کا حقیقی چچا یعنی باپ کا سگا بھائی، وہ نہ ہو تو علاتی چچا یعنی باپ کا پدری بھائی، وہ نہ ہو تو حقیقی چچا کا بیٹا، وہ نہ ہو تو علاتی چچا کا بیٹا، اسی ترتیب سے ان کے پوتے نیچے تک، اور اگر میت کے اپنے بچے یا ان کے بیٹے پوتے نہ ہوں تو میت کے باپ کے بچے (دادے کے بھائی) اسی ترتیب سے عصبہ بنیں گے۔۔۔۔۔ اہل حدیث اور جمہور کا موقف یہی ہے کہ مذکورہ بالا ترتیب کے ساتھ ہی عصبہ بنا جاتا ہے۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا، الَّذِي لَا اخْتِلَافَ فِيهِ، وَالَّذِي أَدْرَكْتُ عَلَيْهِ أَهْلَ الْعِلْمِ بِبَلَدِنَا، فِي وِلَايَةِ الْعَصَبَةِ: أَنَّ الْأَخَ لِلْأَبِ وَالْأُمِّ، أَوْلَى بِالْمِيرَاثِ مِنَ الْأَخِ لِلْأَبِ، وَالْأَخُ لِلْأَبِ أَوْلَى بِالْمِيرَاثِ مِنْ بَنِي الْأَخِ لِلْأَبِ وَالْأُمِّ، وَبَنُو الْأَخِ لِلْأَبِ وَالْأُمِّ، أَوْلَى مِنْ بَنِي الْأَخِ لِلْأَبِ، وَبَنُو الْأَخِ لِلْأَبِ، أَوْلَى مِنْ بَنِي ابْنِ الْأَخِ لِلْأَبِ وَالْأُمِّ، وَبَنُو ابْنِ الْأَخِ لِلْأَبِ، أَوْلَى مِنَ الْعَمِّ أَخِي الْأَبِ لِلْأَبِ وَالْأُمِّ، وَالْعَمُّ أَخُو الْأَبِ لِلْأَبِ وَالْأُمِّ، أَوْلَى مِنَ الْعَمِّ أَخِي الْأَبِ لِلْأَبِ، وَالْعَمُّ أَخُو الْأَبِ لِلْأَبِ، أَوْلَى مِنْ بَنِي الْعَمِّ، أَخِي الْأَبِ","امام مالک رحمہ اللہ نے فرمایا: عصبہ کی رشتہ داری کے متعلق وہ حکم جس پر ہمارے ہاں اجماع ہے، جس میں کوئی اختلاف نہیں ہے اور جس پر میں نے اپنے شہر (مدینہ) کے اہل علم کو پایا ہے۔ یہ ہے کہ (۱) بے شک حقیقی بھائی علاتی بھائی سے زیادہ وراثت کا حق دار ہے۔ (۲) اور علاتی بھائی، حقیقی بھائی کے بیٹوں سے بڑھ کر وراثت کا زیادہ حق دار ہے۔ (۳) اور حقیقی بھائی کے بیٹے، علاتی بھائی کے بیٹوں کی نسبت زیادہ حق دار ہیں۔ (۴) اور علاتی بھائی کے بیٹے حقیقی بھائی کے پوتوں سے زیادہ حقدار ہیں۔ (۵) اور علاتی بھائی کے پوتے اس (حقیقی) چچا سے زیادہ حقدار ہیں جو باپ کا حقیقی بھائی ہے (یعنی میت کے اپنے بھائی حقیقی و علاتی کی ترتیب سے عصبہ بنیں گے اور جب تک ان میں سے یا ان کے بیٹوں، پوتوں یا پڑپوتوں میں سے کوئی زندہ لِلْأَبِ وَالْأُمِّ، وَابْنُ الْعَمِّ لِلْأَبِ، أَوْلَى مِنْ عَمِّ الْأَبِ، أَخِي أَبِي الْأَبِ لِلْأَبِ وَالْأُمِّ.","مل جائے تو چچاؤں والی جانب رخ نہ کریں گے۔ (۶) اور حقیقی چچا (باپ کا حقیقی بھائی) علاتی چچا سے زیادہ حق دار ہے۔ (۷) اور علاتی چچا (باپ کا علاتی یعنی پدری بھائی) حقیقی چچا کے بیٹوں سے زیادہ حقدار ہے۔ (۸) اور (میت کے اپنے) علاتی چچا کے بیٹے، باپ کے حقیقی چچا (دادے کے حقیقی بھائی) سے زیادہ حق دار ہیں۔ (یعنی جب تک میت کے اپنے بچوں اور ان بچوں کے بیٹوں، پوتوں اور پڑپوتوں میں سے کوئی زندہ ہو تو وہی وارث ہے، اگر ان میں سے کوئی بھی موجود نہ ہو تو پھر باپ کے بچوں کو اسی ترتیب سے، پھر دادے کے چچوں کو اسی حساب سے دیکھیں گے)۔","قَالَ مَالِكٌ: وَكُلُّ شَيْءٍ سُئِلْتَ عَنْهُ مِنْ مِيرَاثِ الْعَصَبَةِ، فَإِنَّهُ عَلَى نَحْوِ هَذَا: انْسُبِ الْمُتَوَفَّى وَمَنْ يُنَازِعُ فِي وِلَايَتِهِ مِنْ عَصَبَتِهِ، فَإِنْ وَجَدْتَ أَحَداً مِنْهُمْ يَلْقَى الْمُتَوَفَّى إِلَى أَبٍ، لَا يَلْقَاهُ أَحَدٌ مِنْهُمْ إِلَى أَبٍ دُونَهُ، فَاجْعَلْ مِيرَاثَهُ لِلَّذِي يَلْقَاهُ إِلَى الْأَبِ الْأَدْنَى، دُونَ مَنْ يَلْقَاهُ إِلَى فَوْقِ ذَلِكَ، فَإِنْ وَجَدْتَهُمْ كُلَّهُمْ يَلْقَوْنَهُ إِلَى أَبٍ وَاحِدٍ يَجْمَعُهُمْ جَمِيعاً، فَانْظُرْ أَقْعَدَهُمْ فِي النَّسَبِ، فَإِنْ كَانَ ابْنَ أَبٍ فَقَطْ، فَاجْعَلِ الْمِيرَاثَ لَهُ دُونَ الْأَطْرَفِ، وَإِنْ كَانَ ابْنَ أَبٍ وَأُمٍّ، فَإِنْ وَجَدْتَهُمْ مُسْتَوِينَ، يَنْتَسِبُونَ مِنْ عَدَدِ الْآبَاءِ إِلَى عَدَدٍ وَاحِدٍ، حَتَّى يَلْقَوْا نَسَبَ الْمُتَوَفَّى جَمِيعاً، وَكَانُوا كُلُّهُمْ جَمِيعاً بَنِي أَبٍ، أَوْ بَنِي أَبٍ وَأُمٍّ، فَاجْعَلِ الْمِيرَاثَ بَيْنَهُمْ سَوَاءً، وَإِنْ كَانَ وَالِدُ بَعْضِهِمْ أَخَا وَالِدِ الْمُتَوَفَّى لِلْأَبِ وَالْأُمِّ، وَكَانَ مَنْ سِوَاهُ مِنْهُمْ إِنَّمَا هُوَ أَخُو أَبِي الْمُتَوَفَّى لِأَبِيهِ فَقَطْ، فَإِنَّ الْمِيرَاثَ لِبَنِي أَخِي الْمُتَوَفَّى لِأَبِيهِ وَأُمِّهِ،","امام مالک رحمہ اللہ نے فرمایا: اور عصبات کی وراثت میں سے ہر وہ چیز جس کے متعلق تم سے سوال کیا جائے بلاشبہ وہ اسی (مذکورہ) ترتیب کے مطابق ہوگی۔ (۱) تم میت کو اور (ہر) اس عصبہ کی نسبت کرو جس کی رشتہ داری (اور عصبہ بن کر وراثت کی حقداری) میں جھگڑا کیا جارہا ہو (تو ہر کسی کی سب سے پہلے میت کے ساتھ رشتہ داری کو دیکھیں گے، پھر رشتہ داری میں اس کے باپ اور میت کے باپ کو دیکھیں)، پھر اگر تم ان میں سے کسی کو پاؤ کہ وہ باپ کی طرف (پہنچ کر ہی) میت سے مل جاتا ہے اور ان میں سے دوسرا کوئی بھی اس سے قریبی باپ میں میت سے نہیں ملتا تو تم اس کی وراثت اس (عصبہ) کو دے دو جو سب سے قریبی باپ میں میت سے ملا (اور شریک ہوا) ہو اور اس (رشتہ دار) کو نہ دو جو اس سے اوپر درجے میں میت سے ملتا ہو، مثلاً: میت کا بھائی اور چچا عصبہ بننے میں باہم جھگڑا کریں تو بھائی زیادہ حق دار ہے کیونکہ میت کا اور اس کا باپ ایک ہے اس لیے یہ پہلے باپ ہی میں اکٹھے ہو جاتے ہیں جبکہ چچے کا درجہ دور ہے اور وہ میت کے دوسرے باپ یعنی دادے میں جا کر اکٹھا ہوتا ہے)۔ (۲) پھر اگر تم ان سب کو پاؤ وہ ایک ہی باپ میں مل جاتے ہیں اور وہ باپ ان سب دُونَ بَنِي الْأَخِ لِلْأَبِ، وَذَلِكَ أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَالَ:","﴿ وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ ﴾ [الأنفال: ۷۵]",".","کو اکٹھا کر دیتا ہے تو پھر ان میں سے اس کو دیکھو جو سب میں سب سے زیادہ قریب ہے، چنانچہ اگر (وہ زیادہ قرب والا) صرف باپ کا بیٹا یعنی علاتی رشتہ والا ہو تو وراثت اسی کے لیے کردو، اور دور والے کو چھوڑ دو اگر چہ وہ باپ اور ماں کا بیٹا یعنی حقیقی رشتے والا ہو۔ (مثلاً: ایک وارث میت کے علاتی بھائی کا بیٹا ہو اور دوسرا میت کے حقیقی بھائی کا پوتا ہو تو اگر چہ میت کے ساتھ ان دونوں کا تعلق میت کے باپ میں پہنچ کر بنتا ہے اور وہ سب میت کے باپ ہی کی اولاد ہیں لیکن علاتی بھائی کا بیٹا میت سے صرف ایک درجہ نیچے ہے جبکہ حقیقی بھائی کا پوتا میت سے دو درجے نیچے ہے، اس لیے جو قریب ہے یعنی علاتی بھائی کا بیٹا، وہ عصبہ بن جائے گا۔) (۳) اور اگر تم ان کو برابر درجے والا پاؤ، وہ باپوں کی تعداد میں سے ایک ہی عدد کے ساتھ میت کی طرف منسوب ہوتے ہوں، یہاں تک کہ وہ سب (درمیانی واسطوں کی ایک جیسی تعداد کے ساتھ) فوت شدہ کے نسب میں آملتے ہوں اور وہ سب کے سب علاتی (بھائی کے) بیٹے (یا پوتے یا پڑپوتے) ہوں یا حقیقی (بھائی کے) بیٹے (یا پوتے پڑپوتے) ہوں تو وراثت ان سب کے مابین برابر برابر (تقسیم) کردو۔ (۴) اور اگر (سب کا اکٹھ، ایک باپ میں ہوتا ہو اور میت سے دوری میں بھی سب برابر ہوں لیکن ان میں حقیقی و علاتی کا فرق ہو تو پھر حقیقی رشتے والا زیادہ حقدار ہوگا کیونکہ اس کی قرابت میں قوت ہے۔ چنانچہ اگر ان میں سے بعض کا والد میت کے والد کا سگا اور حقیقی بھائی ہو (یعنی ورثاء سگے بچے کے بیٹے ہوں) اور جوان (ورثاء) میں سے اس کے علاوہ ہوں (ان کا باپ) میت کے باپ کا صرف علاتی بھائی ہو (یعنی وہ علاتی چچا کے بیٹے ہوں) تو بلاشبہ وراثت صرف اور صرف میت کے (باپ کے) سگے بھائی (یعنی سگے چچا) کے بیٹوں کے لیے ہوگی نہ کہ میت کے باپ کے علاتی بھائی (یعنی علاتی چچا) کے بیٹوں کے لیے۔ اور یہ اس وجہ سے ہے کہ بے شک اللہ تعالیٰ نے فرمایا ہے:","﴿ وَأُولُوا الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ ﴾ [الانفال: ۷۵]","اور اللہ کی کتاب میں (خون کے) رشتہ دار آپس میں ایک دوسرے کے زیادہ حقدار ہیں۔ بے شک اللہ تعالیٰ ہر چیز کو خوب جاننے والا ہے۔","قَالَ مَالِكٌ: وَالْجَدُّ أَبُو الْأَبِ، أَوْلَى مِنْ بَنِي الْأَخِ لِلْأَبِ وَالْأُمِّ، وَأَوْلَى مِنَ الْعَمِّ أَخِي الْأَبِ لِلْأَبِ وَالْأُمِّ بِالْمِيرَاثِ، وَابْنُ الْأَخِ لِلْأَبِ وَالْأُمِّ، أَوْلَى مِنَ الْجَدِّ بِوَلَاءِ الْمَوَالِي.","امام مالک رحمہ اللہ نے فرمایا: (میت کے) باپ کا باپ یعنی دادا وراثت پانے میں (میت کے) سگے بھائی کے بیٹوں سے بھی زیادہ حق دار ہے اور وہ دادا (میت کے) باپ کے سگے بھائی یعنی حقیقی چچے سے بھی زیادہ حقدار ہے (کیونکہ عصبہ بالنفس میں ترتیب ملحوظ رکھنا واجب ہے۔ دادا کا تعلق ابوہ سے ہے جبکہ میت کے بھائی اور بھتیجوں کا تعلق اُخُوہ والی جانب سے ہے اور چچا کا تعلق عمومہ والی جہت سے ہے اور یقیناً ابوہ والی جانب اُخُوہ و عمومہ سے مقدم ہے) اور (میت کے) سگے بھائی کا بیٹا (میت کے) آزاد کردہ غلاموں کی ولاء لینے میں (میت کے) دادے سے زیادہ حقدار ہے۔","امام مالک رحمہ اللہ نے وراثت اور ولاء میں فرق کیا ہے۔ ہمارے نزدیک چونکہ ولاء بھی نسب ہی کی طرح کا ایک تعلق ہے اور میت کو ولاء کی وجہ سے جو کچھ ملتا ہے وہ بھی وراثت ہی کے طور پر ہوتا ہے اور اس میں بھی وہی ترتیب ملحوظ رکھنا ضروری ہے جو نسبی عصبات میں ہوتی ہے، لہذا آخری بیان کردہ صورت میں بھی دادا ہی مقدم ہوگا۔ واللہ اعلم"],"568":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے دو فتاویٰ مذکور ہیں۔","امام مالک رحمہ اللہ اس باب میں ذوالارحام کا ذکر کرنا چاہتے ہیں۔ میت کے اصحاب الفرائض بارہ ہیں جن کا بیان کتاب الفرائض کے آغاز میں ذکر کر دیا گیا ہے، ان کے بعد عصبات کا درجہ ہے جن کی تفصیل گزشتہ باب کے شروع میں مذکور ہے۔ ان دونوں قسموں کے علاوہ میت کے باقی رشتہ دار ذوالارحام کہلاتے ہیں، جنھیں چار جہتوں اور جانبوں میں تقسیم کرتے ہیں: (۱) جو میت کی طرف منسوب ہوں یعنی بیٹیوں، پوتیوں اور پڑپوتیوں کی ساری اولاد اور اسی طرح نیچے تک۔ (۲) جن کی طرف میت منسوب ہو یعنی جد فاسد (نانا وغیرہ) اور جدہ فاسدہ (جد فاسد کی ماں وغیرہ اوپر تک) ان کی تعریفیں پیچھے باب: ۸، ۷ کے شروع میں مذکور ہیں۔ (۳) جو میت کے والدین کی طرف منسوب ہوں یعنی ہر قسم کی بہنوں کی اولاد (ہر قسم کے بھانجے)، اخیافی بھائیوں کی اولاد، حقیقی و علاتی بھائیوں کی بیٹیاں، اس طرح ان آخری دونوں قسم کے بھائیوں کے بیٹوں کی بیٹیاں اور اسی طرح نیچے تک۔ (۴) جو میت کے دادا، دادی یا نانا، نانی کی طرف منسوب ہوں یعنی میت کی ہر قسم کی پھوپھیاں (باپ کی تینوں قسم کی بہنیں)، ہر قسم کی خالائیں، ہر قسم کے ماموں اور اخیافی چچے (باپ کے اخیافی بھائی) یہ تمام قسم کے رشتہ دار ذوالارحام یا اولوالارحام ہیں اور جو کوئی بھی ان کے واسطے سے میت کی طرف منسوب ہوگا وہ بھی انھی میں شمار ہوگا۔۔۔۔۔ امام مالک رحمہ اللہ اور امام شافعی رحمہ اللہ کے نزدیک یہ سب بالکل وارث نہیں بنتے اور صرف انھی کی موجودگی میں میت کا ترکہ بیت المال میں جائے گا۔ چنانچہ سیدنا ابوبکر، سیدنا عثمان، سیدنا زید بن ثابت رضی اللہ عنہم، نیز سعید بن مسیب رحمہ اللہ اور سعید بن جبیر رحمہ اللہ کا بھی یہی موقف تھا جبکہ اکثر صحابہ کرام رضی اللہ عنہم اور تابعین رحمہم اللہ، نیز امام ابوحنیفہ رحمہ اللہ، امام احمد رحمہ اللہ اور اہلحدیث کے نزدیک انھیں وراثت مل سکتی ہے بشرطیکہ اصحاب الفرائض اور عصبات میں سے کوئی موجود نہ ہو۔ نیز فرمان نبوی صلی اللہ علیہ وسلم ہے: ’’ماموں اس شخص کا وارث ہے جس کا کوئی وارث نہ ہوگا۔‘‘ (ابوداود: ۲۸۹۹، ترمذی: ۲۱۰۳، ابن ماجہ: ۲۷۳۷، ۲۷۳۸، ان کی سندیں حسن صحیح ہیں) قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا، الَّذِي لَا اخْتِلَافَ فِيهِ، وَالَّذِي أَدْرَكْتُ عَلَيْهِ أَهْلَ الْعِلْمِ بِبَلَدِنَا: أَنَّ ابْنَ الْأَخِ لِلْأُمِّ، وَالْجَدَّ أَبَا الْأُمِّ، وَالْعَمَّ أَخَا الْأَبِ لِلْأُمِّ، وَالْخَالَ، وَالْجَدَّةَ أُمَّ أَبِي الْأُمِّ، وَابْنَةَ الْأَخِ لِلْأَبِ وَالْأُمِّ، وَالْعَمَّةَ، وَالْخَالَةَ، لَا يَرِثُونَ بِأَرْحَامِهِمْ شَيْئاً.","امام مالک رحمہ اللہ نے فرمایا: وہ حکم جس پر ہمارے ہاں اتفاق ہے، جس میں کوئی اختلاف نہیں اور جس پر میں نے اپنے شہر کے اہل علم کو پایا ہے۔ یہ ہے کہ (میت کے) اخیافی بھائی کا بیٹا، نانا، باپ کا اخیافی بھائی (اخیافی چچا)، ماموں، نانے کی ماں (پڑ نانی اور ہر جدہ فاسدہ) حقیقی بھائی کی بیٹی، پھوپھی اور خالہ اپنی رشتہ داریوں کے ساتھ کسی بھی چیز کے وارث نہیں بن سکتے۔","قَالَ: وَإِنَّهُ لَا تَرِثُ امْرَأَةٌ هِيَ أَبْعَدُ نَسَباً مِنَ الْمُتَوَفَّى، مِمَّنْ سُمِّيَ فِي هَذَا الْكِتَابِ بِرَحِمِهَا شَيْئاً، وَإِنَّهُ لَا يَرِثُ أَحَدٌ مِنَ النِّسَاءِ شَيْئاً، إِلَّا حَيْثُ سُمِّينَ، وَإِنَّمَا ذَكَرَ اللهُ تَبَارَكَ وَتَعَالَى فِي كِتَابِهِ مِيرَاثَ الْأُمِّ مِنْ وَلَدِهَا، وَمِيرَاثَ الْبَنَاتِ مِنْ أَبِيهِنَّ وَمِيرَاثَ الزَّوْجَةِ مِنْ زَوْجِهَا، وَمِيرَاثَ الْأَخَوَاتِ لِلْأَبِ وَالْأُمِّ، وَمِيرَاثَ الْأَخَوَاتِ لِلْأَبِ وَمِيرَاثَ الْأَخَوَاتِ لِلْأُمِّ، وَوَرِثَتِ الْجَدَّةُ بِالَّذِي جَاءَ عَنِ النَّبِيِّ صلى الله عليه وسلم فِيهَا، وَالْمَرْأَةُ تَرِثُ مَنْ أَعْتَقَتْ هِيَ نَفْسُهَا، لِأَنَّ اللهَ تَبَارَكَ وَتَعَالَى قَالَ فِي كِتَابِهِ: ﴿فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ﴾ [الأحزاب: ۵].","امام مالک رحمہ اللہ نے فرمایا: اس کتاب (موطا) میں جن کا نام لیا گیا ہے (یعنی گزشتہ فتویٰ میں جن چار عورتوں کا تذکرہ ہے) تو جو کوئی عورت ان سے بھی زیادہ میت کے نسب میں دور ہوگی، وہ بلاشبہ اپنی رشتہ داری کے ساتھ کسی بھی چیز کی وارث نہیں بن سکے گی اور بلاشبہ عورتوں میں سے کوئی بھی کسی بھی چیز کی وارث نہیں بن سکتی، مگر صرف وہ جن کا (قرآن و سنت میں) نام لیا گیا ہے اور یہ بات (ذرا تفصیل سے) اس طرح ہے کہ بیشک اللہ تعالیٰ نے اپنی کتاب میں (مندرجہ ذیل عورتوں کی) میراث کا ذکر کیا ہے: ماں کی وراثت اپنے بیٹے سے، بیٹیوں کی وراثت اپنے باپ سے، بیوی کی وراثت اپنے خاوند سے، حقیقی اور سگی بہنوں کی وراثت، علاتی بہنوں کی وراثت، اخیافی بہنوں کی وراثت اور جدہ (دادی و نانی) اس حدیث کی بنا پر وارث بنتی ہے جو رسول اللہ صلی اللہ علیہ وسلم سے وارد ہوئی ہے، اور عورت اس (غلام، لونڈی کی ولاء) کی بھی وارث بنتی ہے جسے اس نے خود آزاد کیا ہو کیونکہ بلاشبہ اللہ تعالیٰ نے اپنی کتاب میں فرمایا ہے:","﴿ فَإِخْوَانُكُمْ فِي الدِّينِ وَمَوَالِيكُمْ ﴾ [الاحزاب ۵]","’’تو وہ تمھارے دینی بھائی اور تمھارے مولیٰ ہیں۔‘‘","یعنی اللہ تعالیٰ نے غلاموں کے لیے موالی کا لفظ استعمال کیا ہے جو ’’مولیٰ‘‘ کی جمع ہے اور اس کے معنی آزاد کردہ غلام کے ہیں۔ چنانچہ آزاد کرنے والی بعض اوقات کوئی عورت ہوتی ہے، اس لیے وہ اس عورت کے مولیٰ شمار ہوں گے اور ولاء کا تعلق اسی عورت سے قائم ہوگا۔ یاد رہے کہ اس عورت کے ذکر سے پہلے امام مالک رحمہ اللہ نے سات عورتوں کا ذکر کیا ہے اور آٹھویں عورت کا تذکرہ قرآن میں تو نہیں بلکہ حدیث پاک سے ثابت ہے یعنی ہوتی۔ مزید تفصیل کے لیے دیکھیے پیچھے باب: ۱ کا آخری فائدہ۔"],"569":["§خلاصۃ الباب","اس باب میں پانچ روایات ہیں، ایک مرفوع حدیث نبوی صلی اللہ علیہ وسلم ہے جو کہ بخاری ومسلم میں بھی ہے، دو موقوف (آثار صحابہ رضی اللہ عنہم) ہیں جن میں سے ایک صحیح اور ایک حسن ہے اور دو مقطوع (آثار تابعین رحمہم اللہ) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","وہ چیزیں جو کسی وارث کے لیے وراثت کا حقدار بننے میں رکاوٹ بن جاتی ہیں ’’موانع الارث‘‘ کہلاتی ہیں اور وہ تین ہیں (۱) قتل یعنی قاتل اپنے مقتول کا وارث نہیں بن سکتا (۲) غلام اور (۳) اختلاف دین یعنی مسلم اور کافر ایک دوسرے کے وارث نہیں بن سکتے۔ رہا مرتد کا معاملہ تو جمہور کے نزدیک اگر اس کی موت حالت ارتداد میں ہوئی ہو تو دوسرے کفار کی طرح اس کے ساتھ بھی مسلمانوں کا سلسلہ وراثت نہیں چلے گا۔ البتہ امام ابوحنیفہ رحمہ اللہ کے نزدیک اس کی حالت اسلام والی کمائی مسلمان ورثاء میں تقسیم ہوگی، راجح موقف جمہور ہی کا ہے۔ احناف کے ہاں وراثت کے لیے چوتھی چیز ’’اختلاف دارین‘‘ بھی مانع ہے یعنی دارالاسلام اور دارالکفر کے لوگ آپس میں وارث نہیں بن سکتے خواہ وہ مسلمان ہی ہوں، لیکن بہت سے متأخرین احناف نے جمہور کا مؤقف اختیار کرتے ہوئے اسے مانع نہیں سمجھا...... ہر حال ان اشیاء کے علاوہ کوئی چیز وراثت میں مانع نہیں ہے۔ آج کل جو اخبارات میں عاق کرنے کے اشتہارات کا سلسلہ جاری ہے، یہ سراسر خلاف شریعت ہے۔ اگرچہ حکومتی و انتظامی سطح پر ایسے اشتہارات دینے کا یہ فائدہ تو حاصل ہوتا ہے کہ وہ نافرمان بچہ کوئی جرم کرے تو والدین بری الذمہ رہتے ہیں لیکن شرعی طور پر لڑکا خواہ جس قدر بھی نافرمان ہو، وراثت کا بہرحال حقدار رہے گا۔"],"570":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی رحمہ اللہ) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے پانچ فتاویٰ بھی مذکور ہیں۔","کسی جنگ میں یا قتل کی واردات میں یا ٹریفک حادثے میں یا کشتی ڈوبنے میں یا کسی اور آفت و سانحہ میں کچھ رشتہ دار قتل ہو جائیں یا مر جائیں اور یہ علم و یقین حاصل نہ ہو سکے کہ کس کی موت پہلے آئی اور کس کی بعد میں، تو ان مقتولین اور فوت شدگان کی آپس میں وراثت قائم نہ ہو سکے گی ...... دراصل وراثت کی شروط میں سے اولین شرط ہی یہ ہے کہ میت کی موت کے وقت وارث زندہ ہو، خواہ ایک لمحے بعد خود بھی مر جائے، تو جو پہلے مرا ہے وہ بعد والے کا وارث نہ بن سکے گا۔ البتہ بعد میں مرنے والے کو پہلے مرنے والے کی وراثت میں سے حصہ ملے گا، جو بعد ازاں اس کے ورثاء میں تقسیم ہو گا۔"],"571":["§خلاصۃ الباب","اس باب میں دو مقطوع روایات (آثار تابعین رحمہم اللہ) ہیں اور دونوں ہی سنداً ضعیف ہیں۔","لعان والی عورت پر اس کے خاوند کا الزام ہی یہ تھا کہ حمل اس کا نہیں ہے بلکہ زنا کا ہے۔ اب خواہ وہ الزام سچا ہو یا جھوٹا ہر دو صورت میں لعان ہو جانے کے بعد اس بچے کا نسب لعان کرنے والے مرد سے قائم نہ ہوگا۔ رہی وہ اولاد جس کا زنا سے پیدا ہونا ثابت ہو جائے تو ظاہر ہے کہ زانی کے لیے زنا کا بچہ پتھر ہی کی طرح بے کار ہوتا ہے اور بچے کا اس زانی باپ سے شرعی نسب قائم ہی نہیں ہوتا۔ اس لیے مذکورہ دونوں صورتوں میں بچے کی وراثت صرف ماں کی طرف سے قائم ہوگی۔"],"572":["§کتاب کا تعارف","اس کتاب میں ۲۴ ابواب اور ۴۴ روایات ہیں، جن میں سے ۶ مرفوع (احادیث نبویہ صلی اللہ علیہ وسلم)، ۱۲ موقوف (آثار صحابہ رضی اللہ عنہم) اور ۲۶ مقطوع (آثار تابعین رحمہم اللہ) ہیں، ان تمام روایات میں سے ۳۴ سنداً صحیح اور ۱۰ ضعیف ہیں، چنانچہ ۶ مرفوع روایات میں سے ۵ صحیح ہیں اور ایک ضعیف ہے، ۱۲ موقوف روایات میں سے ۶ صحیح اور ۶ ضعیف ہیں اور ۲۶ مقطوع روایات میں سے ۲۳ صحیح اور ۳ ضعیف ہیں۔ نیز امام مالک رحمہ اللہ کے ۷۹ فتاویٰ جات بھی اس کتاب میں مذکور ہیں۔","...... ’’عُقُول‘‘ جمع ہے ’’عَقْل‘‘ کی جس کے معنی دیت اور خون بہا کے ہیں۔ دراصل یہ لفظ اونٹ کا گھٹنا باندھنے کے لیے بولا جاتا ہے۔ اہل عرب میں جب کوئی قاتل خون بہا ادا کرتا تو وہ دیت کے اونٹ جمع کر کے مقتول کے ورثاء کے گھر کے سامنے کھڑا کر کے ان کے گھٹنے باندھ دیتا۔ اسی لیے دیت کا نام ہی ’’عقل‘‘ پڑ گیا، پھر چونکہ یہ دیت قاتل کے عصبہ ورثاء ادا کرتے ہیں اس لیے انھیں عاقلہ کہتے ہیں۔ دیت میں اصل اونٹ ہیں انھی کے بھاؤ کی کمی بیشی کے اعتبار سے ان کے بدلے سونا یا چاندی یا گائیں یا بکریاں یا کپڑے وغیرہ ادا کیے جاتے ہیں۔ عقل کے حوالہ سے ایک توجیہ یہ کی جاتی ہے کہ عقل کا ایک اصل معنی روکنا ہے۔ عقل (سمجھ) کو عقل اس لیے کہتے ہیں وہ آدمی کو غیر شرعی کاموں اور مروت کے خلاف امور سے روکتی ہے۔ دیت اور خون بہا کو عقل اس لیے کہتے ہیں کہ یہ انسان کو قتل اور دیگر فتنوں کے ظلموں سے روکتی ہے۔ عاقلہ خون بہا دینے والوں کو اس لیے عاقلہ کہتے ہیں کہ وہ اپنے خاندان کے افراد کو ظلم وزیادتی سے روکتے ہیں کیونکہ وہ سمجھتے ہیں کہ اگر یہ تعدی و عدوان سے کام لیں گے تو ان کو عقل (دیت) دینا پڑے گی۔","§خلاصۃ الباب","اس باب میں ایک مرفوع روایت (حدیث نبوی صلی اللہ علیہ وسلم) ہے جو سنداً صحیح ثابت ہے۔"],"573":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے چار فتاویٰ بھی مذکور ہیں۔"],"574":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","...... قتل عمد سے مراد وہ قتل ہے جو قصداً اور جانتے بوجھتے ہوئے ایسے آلے سے کیا جائے جو عموماً قتل میں استعمال کیا جاتا ہے۔ اس میں قصاص لازم آتا ہے الا یہ کہ ورثائے مقتول دیت پر راضی ہو جائیں تو اس کی دیت لازم ہوگی جو ذرا مہنگی ہے اور اسے ’’دیت مغلظہ‘‘ کہتے ہیں۔"],"575":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے جو صحیح ثابت ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","قتل خطا کی دو قسمیں ہیں، ایک کو قتل خطا ہی کہتے ہیں اور دوسری کو قتل خطا شبہ عمد۔ پہلی قسم کی تفصیل تو آگے آ رہی ہے۔ دوسری قسم یعنی قتل خطا شبہ عمد سے مراد یہ ہے کہ کوئی مکلف شخص کسی کو ایسی چیز سے مارنے کا ارادہ کرے جس سے عموماً انسان نہیں مرتا، مثلاً: چھڑی یا چھوٹا پتھر وغیرہ۔ اس میں قصاص نہیں ہے بلکہ دیت واجب ہے، البتہ اس کی دیت مغلظہ یعنی سخت ہے اور اسی طرح مہنگی ہے جس طرح کہ گزشتہ باب میں قتل عمد کی دیت بیان ہوئی ہے، رسول اللہ صلی اللہ علیہ وسلم کا فرمان ہے: ’’قتل شبہ عمد کی دیت قتل عمد کی دیت کی طرح مغلظہ ہے اور اس میں قاتل کو قصاصاً قتل نہیں کیا جائے گا‘‘ (ابوداود: ۴۶۶۵۔ اس کی سند حسن ہے) دیت مغلظہ کی تفصیل کے لیے پچھلے باب کی روایت: ۱۴۹۵ دیکھیے۔ قتل خطا میں کبھی تو قاتل کے قصد میں خطا واقع ہوتی ہے، مثلاً: کسی مسلمان کو یہ سمجھ کر تیر مارا یا فائر کیا کہ وہ کوئی جانور ہے یا حربی کافر ہے، اسے ’’خطا فی المحل‘‘ کہتے ہیں اور کبھی کسی جاندار چیز کے قتل کا قصد ہی نہیں کیا گیا ہوتا لیکن ایسا کام ہو جاتا ہے جس سے کوئی مسلمان قتل ہو جاتا ہے، مثلاً: تیر اندازی وغیرہ کی مشق میں کسی ٹارگٹ اور ہدف پر تیر چلایا لیکن وہ کسی مسلمان کو جا لگا، یا گاڑی اور سواری سے کوئی شخص کچلا گیا خواہ سواری بے قابو ہو یا مقتول خود ہی اتفاقاً آگے آ جائے، یا چھت سے کوئی چیز پھینکی لیکن کوئی شخص اس کے نیچے دب گیا یا کسی کو غلط دوائی یا انجکشن لگا دیا وغیرہ۔ اس قتل میں دیت خفیفہ لازم ہوتی ہے جس کا بیان آگے آ رہا ہے۔"],"576":["§خلاصۃ الباب","اس باب میں کوئی روایت نہیں ہے، البتہ امام مالک رحمہ اللہ کے چار فتاویٰ جات مذکور ہیں۔","حَدَّثَنِي مَالِكٌ: أَنَّ الْأَمْرَ الْمُجْتَمَعَ عَلَيْهِ عِنْدَهُمْ فِي الْخَطَإِ: أَنَّهُ لَا يُعْقَلُ حَتَّى يَبْرَأَ الْمَجْرُوحُ وَيَصِحَّ، وَأَنَّهُ إِنْ كُسِرَ عَظْمٌ مِنَ الْإِنْسَانِ يَدٌ أَوْ رِجْلٌ، أَوْ غَيْرُ ذَلِكَ مِنَ الْجَسَدِ خَطَأً، فَبَرَأَ وَصَحَّ وَعَادَ لِهَيْئَتِهِ، فَلَيْسَ فِيهِ عَقْلٌ، فَإِنْ نَقَصَ أَوْ كَانَ فِيهِ عَثَلٌ، فَفِيهِ مِنْ عَقْلِهِ بِحِسَابِ مَا نَقَصَ مِنْهُ.","امام مالک رحمہ اللہ نے فرمایا: یقیناً غلطی سے زخمی کر دینے کے متعلق ان کے ہاں اس حکم پر اجماع ہے کہ بلاشبہ اس کی دیت ادا نہ کی جائے گی، یہاں تک کہ زخمی شخص (کا زخم) ٹھیک ہو جائے اور وہ صحت یاب ہو جائے۔ (یہ انتظار اس لیے ہے کہ ممکن ہے کہ یہ زخم موت کا باعث بن جائے اور قتل خطا کی دیت لازم ہو جائے۔) اور بلاشبہ اگر کسی انسان کی کوئی ہڈی غلطی سے توڑ دی جائے، مثلاً: ہاتھ یا پاؤں اور ان کے علاوہ جسم کا کوئی اور عضو، پھر وہ شفا پا لے اور صحت یاب ہو جائے اور اپنی (پہلے والی) حالت پر لوٹ آئے تو اس میں کوئی دیت نہ ہوگی اور اگر (اس عضو میں کوئی) نقص پیدا ہو جائے یا اس میں عدم استواء ہو جائے (وہ ہڈی غلط طریقے سے ناہموار ہو کر جڑے، سیدھی نہ ہو سکے) تو پھر اسی حساب سے دیت (واجب) ہوگی جو کہ نقص آیا ہو۔","قَالَ مَالِكٌ: فَإِنْ كَانَ ذَلِكَ الْعَظْمُ مِمَّا جَاءَ فِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم عَقْلٌ مُسَمًّى، فَبِحِسَابِ مَا فَرَضَ فِيهِ النَّبِيُّ صلى الله عليه وسلم، وَمَا كَانَ مِمَّا لَمْ يَأْتِ فِيهِ عَنِ النَّبِيِّ صلى الله عليه وسلم عَقْلٌ مُسَمًّى، وَلَمْ تَمْضِ فِيهِ سُنَّةٌ وَلَا عَقْلٌ مُسَمًّى، فَإِنَّهُ يُجْتَهَدُ فِيهِ.","امام مالک رحمہ اللہ نے فرمایا: اگر تو وہ ہڈی (کا زخم) ان (بیان کردہ زخموں) میں سے ہو جن کے متعلق نبی کریم صلی اللہ علیہ وسلم سے متعین دیت وارد ہوئی ہو تو (اس میں دیت کا وجوب) اسی حساب سے ہوگا، جو اس میں نبی کریم صلی اللہ علیہ وسلم نے مقرر فرمایا ہے اور جو (زخم) ایسا ہو کہ اس کے متعلق نبی کریم صلی اللہ علیہ وسلم سے کوئی مقرر دیت ثابت نہ ہو اور نہ اس میں کوئی سنت (جاری) ہو اور نہ کوئی متعین دیت (کا فیصلہ) جاری ہوا ہو تو بلاشبہ اس کے بارے میں اجتہاد کیا جائے گا۔","قَالَ مَالِكٌ: وَلَيْسَ فِي الْجِرَاحِ فِي الْجَسَدِ إِذَا كَانَتْ خَطَأً عَقْلٌ إِذَا بَرَأَ الْجُرْحُ وَعَادَ لِهَيْئَتِهِ، فَإِنْ كَانَ فِي شَيْءٍ مِنْ ذَلِكَ عَثَلٌ، أَوْ شَيْنٌ فَإِنَّهُ يُجْتَهَدُ فِيهِ، إِلَّا الْجَائِفَةَ، فَإِنَّ فِيهَا ثُلُثَ دِيَةِ النَّفْسِ.","امام مالک رحمہ اللہ نے فرمایا: اور جسم میں (پہنچنے والے) زخم میں جب کہ وہ غلطی سے (لگا) ہو، کوئی دیت نہیں پڑتی جس وقت کہ زخم شفایاب ہو جائے اور (عضو، ہڈی) اپنی حالت پر لوٹ آئے۔ ہاں اگر ان میں سے کسی میں ناہموار جڑاؤ یا کوئی عیب (واقع) ہو تو اس کے متعلق اجتہاد کیا جائے گا سوائے جائفہ، یعنی پیٹ کے اندر تک پہنچنے والے زخم کے، کیونکہ بلاشبہ اس میں جان (تلف ہو جانے) کی دیت کا تہائی (لازم) ہے۔","’’جائفہ‘‘ سے مراد وہ زخم ہے جو پیٹ یا سر یا پشت کے اندر تک چلا جائے اور بعض روایات میں اس کی دیت کی مقدار تہائی ثابت ہے یعنی کل دیت ۱۰۰ اونٹ کا تیسرا حصہ پڑتا ہے۔ (نسائی: ۴۸۵۷، ۴۸۶۰۔ اس کی سند حسن ہے) راجح یہ ہے کہ غلطی کی صورت میں اس میں بھی اجتہاد کے ساتھ سزا دی جائے گی۔ واللہ اعلم قَالَ مَالِكٌ: وَلَيْسَ فِي مُنَقِّلَةِ الْجَسَدِ عَقْلٌ، وَهِيَ مِثْلُ مُوضِحَةِ الْجَسَدِ.","امام مالک رحمہ اللہ نے فرمایا: جسم کے منقلہ زخم (جو ہڈی کو اپنی جگہ سے منتقل کر دے) میں کوئی دیت نہیں ہے اور یہ جسم کے موضحہ زخم (جو ہڈی کو ننگا کر دیتا ہے) جیسا ہے۔","منقلہ زخم کا تذکرہ بعض روایات میں ثابت ہے۔ (نسائی: ۴۸۵۷، ۴۸۶۰، احمد: ۲۱۷/۲، دارمی، کتاب الدیات: ۱۲۔ اس کی سند حسن ہے، نیز دیکھیے مراسیل ابی داود: ۲۵۷، نسائی فی الکبری: ۵۷/۸، ۵۸، ارواء الغلیل: ۲۲۱۲) اگر یہ زخم قصداً لگایا جائے تو اس میں پندرہ اونٹ دیت ادا کی جاتی ہے اور خطا سے ہو تو کوئی دیت نہیں ہے۔ موضحہ میں پانچ اونٹ لازم ہیں اور اگر یہ بھی غلطی سے ہو تو کچھ بھی دیت نہیں پڑتی، کیونکہ زخم بالآخر بھر ہی جاتا ہے، ہاں اگر زخم درست نہ ہو اور اسی کی بنا پر موت آجائے تو پھر قتل خطا کی دیت پڑتی ہے۔","قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا: أَنَّ الطَّبِيبَ إِذَا خَتَنَ فَقَطَعَ الْحَشَفَةَ: إِنَّ عَلَيْهِ الْعَقْلَ، وَأَنَّ ذَلِكَ مِنَ الْخَطَإِ الَّذِي تَحْمِلُهُ الْعَاقِلَةُ، وَأَنَّ كُلَّ مَا أَخْطَأَ بِهِ الطَّبِيبُ أَوْ تَعَدَّى إِذَا لَمْ يَتَعَمَّدْ ذَلِكَ، فَفِيهِ الْعَقْلُ.","امام مالک رحمہ اللہ نے فرمایا: وہ حکم جس پر ہمارے ہاں اجماع ہے، یہ ہے کہ بے شک ہمارے ہاں طبیب (ڈاکٹر، معالج، حکیم، جراح وغیرہ) جب ختنہ کرے اور حشفہ (عضو تناسل کا اگلا سرا جو ختنہ کے بعد کھال کٹنے سے کھل جاتا ہے) کاٹ ڈالے تو بلاشبہ اس پر دیت لازم ہے اور یقیناً یہ اس خطا (والے جرائم) میں سے ہے جسے عاقلہ رشتہ دار اٹھاتے (اور برداشت کرتے) ہیں اور بلاشبہ جب بھی طبیب اس میں خطا کا ارتکاب کرے یا حد سے تجاوز کرے (کہ بوقت جراحی یا بوقت آپریشن کھال زیادہ چیر ڈالے یا کوئی اور غلطی کرے) تو اس میں دیت ہے (بشرطیکہ) جب اس نے عمداً ایسا نہ کیا ہو۔","اگر عمداً ایسا کرے گا تو اس سے قصاص لیا جائے گا، اسی طرح جو شخص طب میں ماہر نہ ہو اور تکلف سے جھوٹ موٹ طبیب بن کر علاج کرے اور کوئی نقصان کر بیٹھے تو وہ ضامن ہوگا۔ (ابو داود: ۴۵۸۶، نسائی: ۴۸۳۴، ابن ماجہ: ۳۴۶۶۔ اس کی سند حسن ہے۔ عاقلہ سے مراد آدمی کے باپ کی جانب سے مذکر رشتہ دار ہیں، جنھیں عصبہ یا آبائی مذکر رشتہ دار بھی کہا جا سکتا ہے۔"],"577":["§خلاصۃ الباب","اس باب میں تین مقطوع روایات (آثار تابعین رحمہم اللہ) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔"],"578":["§خلاصۃ الباب","اس باب میں تین روایات ہیں جن میں سے دو مرفوع (احادیث نبویہ) ہیں جو کہ بخاری و مسلم میں بھی موجود ہیں اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے اور وہ بھی سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے چھ فتاویٰ جات بھی مذکور ہیں۔"],"579":["§خلاصۃ الباب","اس باب میں دو مقطوع روایات (آثار تابعین رحمہم اللہ) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے چار فتاویٰ جات بھی مذکور ہیں۔"],"580":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی رضی اللہ عنہ) ہے جس کی سند صحیح ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","جمہور فقہاء کے نزدیک وہ شخص جو کسی کی آنکھ تو ضائع نہ کرے البتہ اس کی بینائی ختم کر دے، اس کا فیصلہ قاضی کی صوابدید پر منحصر رکھتے ہیں لیکن اہل حدیث کے نزدیک اس بارے میں یہ فرمانِ نبوی صلی اللہ علیہ وسلم فیصلہ کن ہے جسے سیدنا عبد اللہ بن عمرو بن عاص رضی اللہ عنہما نے روایت کیا ہے، فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس آنکھ جو اپنی جگہ پر قائم رہے (صرف بینائی ضائع ہو) کے متعلق اس کی تہائی دیت کا فیصلہ فرمایا۔ (ابوداود: ۴۵۶۷، نسائی: ۴۸۴۴۔","اس کی سند حسن ہے۔) مثلاً آنکھ کی کل دیت پچاس اونٹ ہے تو مذکورہ بالا صورت میں پچاس کا تیسرا حصہ ادا کرنا واجب ہے۔"],"581":["§خلاصۃ الباب","اس باب میں چار روایات ہیں، جن میں سے ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے جو کہ سنداً ضعیف ہے اور باقی تین مقطوع (آثار تابعین رحمہم اللہ) ہیں جو کہ صحیح ثابت ہیں، نیز امام مالک رحمہ اللہ کے آٹھ فتاویٰ بھی مذکور ہیں۔"],"582":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی رحمہ اللہ) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔"],"583":["§خلاصۃ الباب","اس باب میں تین روایات ہیں جن میں سے دو موقوف (آثار صحابہ رضی اللہ عنہم) اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے اور سنداً سب صحیح ہیں۔","اس باب میں امام مالک رحمہ اللہ نے اہل مدینہ کے وہ اقوال ذکر کیے ہیں جن میں دانتوں کی دیت حدیث میں بیان شدہ دیت کی بجائے قیاس پر مبنی ہے۔ غالباً انھیں یا تو حدیث پہنچی ہی نہیں یا وہ معتبر ذریعے سے نہ پہنچی ہوگی، واللہ اعلم۔ حدیث کے مطابق فیصلہ آئندہ باب میں خود امام صاحب بیان کر دیں گے۔"],"584":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک موقوف اور ایک مقطوع ہے اور دونوں سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔"],"585":["§خلاصۃ الباب","اس باب میں دو مقطوع روایات (آثار تابعین رحمہم اللہ) ہیں جو سنداً ضعیف ہیں، نیز امام مالک رحمہ اللہ کے چار فتاویٰ جات بھی مذکور ہیں۔"],"586":["§خلاصۃ الباب","اس باب میں دو مقطوع روایات (آثار تابعین رحمہم اللہ) ہیں اور دونوں سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","وہ تمام غیر مسلم لوگ جو اسلامی سلطنت کے ماتحت جزیہ دے کر رہتے ہیں، اہل ذمہ کہلاتے ہیں، کیونکہ جزیے کے بدلے اسلامی حکومت ان غیر مسلموں کی جان و مال کی حفاظت کی ذمہ دار ہوتی ہے۔"],"587":["§خلاصۃ الباب","اس باب میں چار مقطوع روایات (آثار تابعین رحمہم اللہ) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے پانچ فتاویٰ جات بھی مذکور ہیں۔","امام مالک رحمہ اللہ، امام ابو حنیفہ رحمہ اللہ اور امام شافعی رحمہ اللہ کے نزدیک صرف اور صرف قتل خطا کی دیت کی ادائیگی میں قاتل کے والد کی طرف سے مذکر رشتہ دار جنھیں عاقلہ یا عصبہ بھی کہتے ہیں، اس قاتل کے ساتھ شریک رہیں گے اور قتل عمد کی دیت صرف قاتل ہی کے ذمے ہے۔ ہاں اگر کوئی تعاون کرنا چاہے تو اس کی مرضی ہے ورنہ قاتل کے سوا یہ کسی پر واجب نہیں۔ اہل حدیث کے ہاں چونکہ رسول اللہ صلی اللہ علیہ وسلم سے اس فرق کا ثبوت نہیں مل سکا اس لیے آپ صلی اللہ علیہ وسلم کے فرمان میں عموم باقی ہے اور عاقلہ رشتہ دار دیت کی ادائیگی میں قاتل کے ساتھ شریک رہیں گے، خواہ قتل خطا کی دیت ہو یا قتل عمد کی۔"],"588":["§خلاصۃ الباب","اس باب میں چار روایات ہیں۔ دو مرفوع (احادیث نبویہ صلی اللہ علیہ وسلم) ہیں جن میں سے ایک صحیح اور ایک ضعیف سند والی ہے، اور دو مقطوع (آثار تابعین رحمہم اللہ) ہیں اور ان میں سے بھی ایک صحیح اور ایک ضعیف ہے، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔","دیت مقتول شخص کا مال شمار ہوتی ہے، لہٰذا میت کے دوسرے اموال کی طرح دیت میں بھی وراثت قائم ہوگی، بعض دیتیں نسبتاً سخت ہوتی ہیں اور ان میں مہنگے اونٹ ادا کرنا ہوتے ہیں۔"],"589":["§خلاصۃ الباب","اس باب میں ایک حدیث نبوی صلی اللہ علیہ وسلم ہے جو کہ بخاری و مسلم میں بھی موجود ہے، نیز امام مالک رحمہ اللہ کے بارہ فتاویٰ جات بھی مذکور ہیں۔"],"590":["§خلاصۃ الباب","اس باب میں دو موقوف روایات یعنی آثار صحابہ رضی اللہ عنہم ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔"],"591":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت یعنی اثر تابعی رحمہ اللہ ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔"],"592":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے پانچ فتاویٰ جات بھی مذکور ہیں۔"],"593":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے چار فتاویٰ جات مذکور ہیں۔","سیدنا انس رضی اللہ عنہ سے روایت ہے، کہتے ہیں کہ میں نے نہیں دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس قصاص کا کوئی بھی معاملہ لایا گیا ہو اور آپ صلی اللہ علیہ وسلم نے اس میں معافی کا حکم نہ دیا ہو۔ (ابوداود: ۴۴۹۷، نسائی: ۴۷۸۸، ابن ماجہ: ۲۶۹۲، احمد: ۳/۲۱۳۔ اس کی سند صحیح ہے۔) اس روایت میں حکم سے مراد مشورہ و نصیحت ہے۔","حَدَّثَنِي يَحْيَى، عَنْ مَالِكٍ، أَنَّهُ أَدْرَكَ مَنْ يَرْضَى مِنْ أَهْلِ الْعِلْمِ يَقُولُونَ فِي الرَّجُلِ إِذَا أَوْصَى، أَنْ يُعْفَى عَنْ قَاتِلِهِ إِذَا قَتَلَ عَمْداً: إِنَّ ذَلِكَ جَائِزٌ لَهُ، وَأَنَّهُ أَوْلَى بِدَمِهِ مِنْ غَيْرِهِ مِنْ أَوْلِيَائِهِ مِنْ بَعْدِهِ۔","امام مالک رحمہ اللہ نے فرمایا کہ: بلاشبہ انھوں نے ان اہل علم کو پایا جن پر وہ راضی تھے، وہ (سب) فرماتے تھے: آدمی جب یہ وصیت کرے کہ اس کے قاتل کو معاف کر دیا جائے، جس وقت کہ اس (قاتل) نے اس (وصیت کرنے والے) کو عمداً قتل کیا ہو تو بلاشبہ یہ (وصیت) اس کے لیے جائز ہے اور یقیناً وہ اپنے علاوہ افراد یعنی اپنے بعد اپنے اولیاء (وارثوں) کی نسبت خود اپنے خون کا سب سے زیادہ حق رکھتا ہے۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَعْفُو عَنْ قَتْلِ الْعَمْدِ بَعْدَ أَنْ يَسْتَحِقَّهُ وَيَجِبَ لَهُ: إِنَّهُ لَيْسَ عَلَى الْقَاتِلِ عَقْلٌ يَلْزَمُهُ، إِلَّا أَنْ يَكُونَ الَّذِي عَفَا عَنْهُ اشْتَرَطَ ذَلِكَ عِنْدَ الْعَفْوِ عَنْهُ۔","امام مالک رحمہ اللہ نے اس شخص کے بارے میں فرمایا: جو قتلِ عمد کو معاف کر دیتا ہے بعد اس کے کہ وہ اس (خون کا قصاص) کا حق پا لے اور وہ (قصاص) اس کے لیے ثابت ہو جائے تو بلاشبہ (معاف کیے جانے والے) قاتل پر کوئی دیت بھی لازم نہ ہوگی، الا یہ کہ جس شخص نے معافی دی ہو، اس نے اسے معاف کرتے وقت اس (دیت) کی شرط لگا لی ہو۔","قَالَ مَالِكٌ فِي الْقَاتِلِ عَمْداً إِذَا عُفِيَ عَنْهُ: أَنَّهُ يُجْلَدُ مِئَةَ جَلْدَةٍ وَيُسْجَنُ سَنَةً۔","امام مالک رحمہ اللہ نے عمد قتل کرنے والے شخص کے بارے میں فرمایا: جب کہ اسے معافی دے دی جائے تو بلاشبہ (معافی کے باوجود) اسے سو کوڑے لگائے جائیں اور اسے ایک سال قید رکھا جائے۔","قرآن و سنت سے اس موقف کے لیے کوئی دلیل ثابت نہیں ہے اور نہ ہی عام فقہاء اور جمہور اس کے قائل ہیں۔","قَالَ مَالِكٌ: وَإِذَا قَتَلَ الرَّجُلُ عَمْداً، وَقَامَتْ","امام مالک رحمہ اللہ نے فرمایا: اور جب آدمی عمداً قتل کرے اور عَلَى ذَلِكَ الْبَيِّنَةُ، وَلِلْمَقْتُولِ بَنُونَ وَبَنَاتٌ، فَعَفَا الْبَنُونَ وَأَبَى الْبَنَاتُ أَنْ يَعْفُونَ، فَعَفْوُ الْبَنِينَ جَائِزٌ عَلَى الْبَنَاتِ، وَلَا أَمْرَ لِلْبَنَاتِ مَعَ الْبَنِينَ فِي الْقِيَامِ بِالدَّمِ وَالْعَفْوِ عَنْهُ۔","اس پر دلیل بھی قائم ہو جائے اور مقتول کے کچھ بیٹے اور کچھ بیٹیاں ہوں، پھر بیٹے تو معاف کر دیں اور بیٹیاں معاف کرنے سے انکار کر دیں تو بلاشبہ بیٹوں کی معافی بیٹیوں پر نافذ ہوگی اور خون کا مطالبہ کرنے میں اور اسے معاف کرنے میں بیٹیوں کے پاس بیٹوں کی موجودگی میں کوئی اختیار نہیں ہوتا۔","جبکہ امام ابوحنیفہ رحمہ اللہ، امام شافعی رحمہ اللہ اور اہلحدیث کے نزدیک سب کے لیے معاف کرنے اور مطالبہ کرنے کا حق اور گنجائش ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے مقتول کے اولیاء یعنی تمام ورثاء کو اختیار دیا ہے کہ چاہیں تو قصاص لیں اور چاہیں تو دیت لیں۔ (ابوداود: ۴۵۰۶، ترمذی: ۱۳۸۷، ابن ماجہ: ۲۶۲۶۔ اس کی سند صحیح ہے۔) اور ورثاء میں جس طرح لڑکے شامل ہیں اسی طرح لڑکیاں بھی شامل ہیں۔ نیز اکثر روایات میں ’’مَنْ‘‘ کا لفظ ورثاء کے لیے استعمال ہوا ہے جو مذکر و مؤنث سب پر بولا جاتا ہے، لہذا مقتول کی بیٹیاں بھی معاف کرنے کا حق رکھتی ہیں۔ یاد رہے کہ ورثاء میں سے کوئی ایک شخص قصاص معاف کر دے تو باقی ورثاء قصاص نہیں لے سکتے کیونکہ یہ تو ہو نہیں سکتا کہ معاف کرنے والے کا حصہ چھوڑ کر باقی جسم کو قتل کر دیا جائے، اور قاتل کے جسم کا کچھ حصہ زندہ اور کچھ مردہ کر دیا جائے، اس لیے ایک وارث کی معافی سے قصاص ساقط ہو جاتا ہے۔ رہا دیت کا مسئلہ تو اسے جو جو وارث معاف کرے گا، اس کے حصے کے مطابق دیت معاف ہوتی جائے گی اور باقی دیت قاتل کے ذمے رہے گی۔"],"594":["§خلاصۃ الباب","اس باب میں ایک مقطوع روایت (اثر تابعی رحمہ اللہ) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْأَمْرُ الْمُجْتَمَعُ عَلَيْهِ عِنْدَنَا: أَنَّ مَنْ كَسَرَ يَداً أَوْ رِجْلاً عَمْداً، أَنَّهُ يُقَادُ مِنْهُ وَلَا يَعْقِلُ۔","امام مالک رحمہ اللہ نے فرمایا: وہ حکم جس پر ہمارے ہاں اجماع ہے، یہ ہے کہ بلاشبہ جس شخص نے کوئی ہاتھ یا پاؤں عمداً توڑ ڈالا تو یقیناً اس سے قصاص لیا جائے گا اور وہ دیت ادا نہیں کرے گا۔","کیونکہ قرآن مجید میں زخموں کے متعلق صرف قصاص کا ذکر ہے۔ (سورۂ مائدہ ۵:۴۵) لیکن احادیث مبارکہ کی روشنی میں باقی ائمہ کرام کے نزدیک صرف ان زخموں میں قصاص ہے جن میں مماثلت اور برابری ممکن ہو جیسا کہ اعضائے بدن کا کاٹنا۔ اگر مماثلت ممکن نہ ہو تو پھر دیت ہی سے کام چلے گا۔ رہا ہڈی توڑنے کا معاملہ تو امام ابوحنیفہ رحمہ اللہ اور امام شافعی رحمہ اللہ کے نزدیک سوائے دانت کے کسی اور ہڈی میں قصاص نہ ہوگا جبکہ امام احمد رحمہ اللہ کے نزدیک صرف اس ہڈی کے توڑنے میں قصاص نہ ہوگا جس سے ہلاکت کا اندیشہ ہو، مثلاً: سر کی ہڈی وغیرہ، باقی ہر ہڈی میں قصاص ہوگا اور یہی راجح ہے۔ واللہ اعلم قَالَ مَالِكٌ: وَلَا يُقَادُ مِنْ أَحَدٍ حَتَّى تَبْرَأَ جِرَاحُ صَاحِبِهِ فَيُقَادُ مِنْهُ، فَإِنْ جَاءَ جُرْحُ الْمُسْتَقَادِ مِنْهُ مِثْلَ جُرْحِ الْأَوَّلِ حِينَ يَصِحُّ فَهُوَ الْقَوَدُ، وَإِنْ زَادَ جُرْحُ الْمُسْتَقَادِ مِنْهُ أَوْ مَاتَ فَلَيْسَ عَلَى الْمَجْرُوحِ الْأَوَّلِ الْمُسْتَقِيدِ شَيْءٌ، وَإِنْ بَرَأَ جُرْحُ الْمُسْتَقَادِ مِنْهُ، وَشَلَّ الْمَجْرُوحُ الْأَوَّلُ، أَوْ بَرَأَتْ جِرَاحُهُ وَبِهَا عَيْبٌ أَوْ نَقْصٌ أَوْ عَثَلٌ، فَإِنَّ الْمُسْتَقَادَ مِنْهُ لَا يَكْسِرُ الثَّانِيَةَ وَلَا يُقَادُ بِجُرْحِهِ۔ قَالَ: وَلَكِنَّهُ يُعْقَلُ لَهُ بِقَدْرِ مَا نَقَصَ مِنْ يَدِ الْأَوَّلِ أَوْ فَسَدَ مِنْهَا، وَالْجِرَاحُ فِي الْجَسَدِ عَلَى مِثْلِ ذَلِكَ۔","امام مالک رحمہ اللہ نے فرمایا: اور کسی بھی شخص سے قصاص نہ لیا جائے گا یہاں تک کہ اس کے (زخمی) ساتھی کا زخم صحیح ہو جائے تو پھر اس (زخمی کرنے والے) سے قصاص لیا جائے، پھر جس سے قصاص لیا گیا، اگر اس کا زخم جب صحیح ہو جائے تو اس پہلے (زخمی) شخص کے زخم کی طرح ہو جائے تو یہ (برابر برابر) قصاص ہو گیا، اور اگر جس سے قصاص لیا گیا، اس کا زخم بڑھ گیا یا (اس زخم کی وجہ سے) وہ مر گیا تو قصاص لینے والے پہلے زخمی شخص پر کچھ (تاوان) نہ ہوگا، اور اگر جس سے قصاص لیا گیا تھا اس کا زخم تو ٹھیک ہو گیا اور (لیکن قصاص لینے والے) پہلے زخمی شخص کا ہاتھ شل (اور بے کار) ہو گیا یا اس کا زخم تو ٹھیک ہو گیا لیکن اس میں عیب یا نقص یا ناہموار جڑاؤ پیدا ہو گیا تو جس سے قصاص لیا جا چکا ہے اس کی ہڈی کو دوبارہ نہ توڑا جائے گا اور اس (زخمی) کے زخم کے بدلے اس سے (دوبارہ) قصاص نہ ہوگا۔ امام مالک رحمہ اللہ نے فرمایا: اور لیکن پہلے شخص کے ہاتھ میں جتنا نقص واقع ہوا ہو یا اس میں خرابی آئی ہو (یعنی شل ہو گیا ہو تو) اس کے بقدر اسے دیت دلائی جائے گی۔ اس جسم کے (دوسرے تمام) زخم بھی اسی طرح ہی (کا حکم رکھتے) ہیں۔","امام مالک رحمہ اللہ، امام ابوحنیفہ رحمہ اللہ اور اہلحدیث کے ہاں زخم مکمل ٹھیک ہونے کے بعد ہی قصاص ہوگا لیکن امام شافعی رحمہ اللہ فی الحال اور فوری قصاص کے قائل ہیں۔","قَالَ مَالِكٌ: وَإِذَا عَمَدَ الرَّجُلُ إِلَى امْرَأَتِهِ فَفَقَأَ عَيْنَهَا، أَوْ كَسَرَ يَدَهَا، أَوْ قَطَعَ إِصْبَعَهَا، أَوْ شِبْهَ ذَلِكَ، مُتَعَمِّداً لِذَلِكَ، فَإِنَّهَا تُقَادُ مِنْهُ، وَأَمَّا الرَّجُلُ يَضْرِبُ امْرَأَتَهُ بِالْحَبْلِ أَوْ","امام مالک رحمہ اللہ نے فرمایا: جب آدمی اپنی بیوی کا قصد کرے اور اس کی آنکھ (عمداً) پھوڑ ڈالے یا اس کا ہاتھ توڑ ڈالے یا اس کی انگلی کاٹ ڈالے یا اس کے مشابہ (کوئی اور زخم لگائے)، اس حال میں کہ وہ جان بوجھ کر ایسا کرنے والا بِالسَّوْطِ، فَيُصِيبُهَا مِنْ ضَرْبِهِ مَا لَمْ يُرِدْ وَلَمْ يَتَعَمَّدْ، فَإِنَّهُ يَعْقِلُ مَا أَصَابَ مِنْهَا عَلَى هَذَا الْوَجْهِ، وَلَا يُقَادُ مِنْهُ.","ہو تو بلا شبہ اس سے قصاص لیا جائے گا، اور رہی یہ صورت کہ آدمی اپنی بیوی کو رسی سے یا کوڑے سے مارتا پیٹتا ہے تو وہ اپنی اس مار میں اسے کوئی نقصان پہنچا دیتا ہے جس کا اس نے نہ ارادہ کیا ہوتا ہے اور نہ وہ عمداً ایسا کرتا ہے تو بلا شبہ اس طریقے سے اس نے جو اسے نقصان پہنچایا ہو، وہ اس کی صرف دیت ہی ادا کرے گا اور اس سے قصاص نہ لیا جائے گا۔"],"595":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت یعنی اثر صحابی رضی اللہ عنہ ہے جو سنداً ضعیف ہے۔","سائبہ وہ غلام ہے جسے آزاد کرنے والے پر اس غلام کا کوئی حق اور تعلق باقی نہ رہے، جانوروں میں سائبہ سے مراد بتوں کے نام پر چھوڑے جانے والے جانور ہیں جنھیں گویا آزاد چھوڑ دیا جاتا ہے اور غلاموں میں سے بھی سائبہ کو گویا بالکل آزاد چھوڑا جاتا ہے۔ چنانچہ سائبہ غلام وہ ہے جس کی آزادی میں یہ شرط قائم کی جائے کہ نہ تو اس کا آقا اس کی ولاء کا وارث بنے گا اور نہ اس کی طرف سے کسی دیت کی چٹی بھرے گا، سائبہ غلام کے متعلق پیچھے کتاب العتق کا آخری باب بھی گزر چکا ہے۔ امام مالک رحمہ اللہ سائبہ غلام کی سائبہ والی حیثیت کو صرف مکروہ سمجھتے ہیں جبکہ باقی ائمہ کرام اور محدثین اس شرط کو سرے سے باطل قرار دیتے ہیں۔ چنانچہ ان کے نزدیک غلام آزاد تو ہو جاتا ہے لیکن اس کا تعلق آقا سے بحال رہتا ہے، لہذا وہ آقا اس کی ولاء کا بھی وارث بنے گا اور اگر غلام پر کسی دیت کی چٹی پڑ جائے تو اس کی ادائیگی میں آقا بھی شریک ہوگا۔ سیدنا عبداللہ بن مسعود رضی اللہ عنہ فرماتے ہیں: اہل اسلام سائبہ نہیں بناتے۔ (بخاری: ۶۷۵۳)"],"596":["§کتاب کا تعارف","اس کتاب میں پانچ ابواب اور دو مرفوع روایات یعنی احادیث نبویہ صلی اللہ علیہ وسلم ہیں جو کہ پہلے ہی باب میں موجود ہیں اور بخاری و مسلم کی روایات میں سے ہیں، نیز امام مالک رحمہ اللہ کے اکیس فتاوی جات بھی اس کتاب میں مذکور ہیں۔","قسامہ سے مراد امام مالک رحمہ اللہ اور امام شافعی رحمہ اللہ کے نزدیک وہ پچاس قسمیں ہیں جو گواہ نہ ہونے کی صورت میں مقتول کے ورثاء مجرم کے خلاف قتل ثابت کرنے کے لیے اٹھائیں۔ امام ابوحنیفہ رحمہ اللہ کے نزدیک وہ پچاس قسمیں مراد ہیں جنھیں وہ اہل محلہ اپنی بے گناہی ثابت کرنے کے لیے اٹھاتے ہیں جن کے خلاف قتل کا دعویٰ کیا گیا ہو۔۔۔۔۔ دراصل یہ دونوں مقام ابراہیم کے درمیان میں کھڑے ہو کر یہ قسمیں کھاتے تھے، چونکہ اللہ کی قسم کھانا بہت نازک معاملہ ہے اس لیے اگر یہ قسم جھوٹ پر اٹھائی جائے اور خصوصاً اجتماعی طور پر جھوٹی قسمیں کھائی جائیں تو ان کا نتیجہ وہاں بھی بہت ہی جلد دیکھنے میں آتا ہے، رسول اللہ صلی اللہ علیہ وسلم نے اسے دور جاہلیت ہی کی صورت پر قائم رکھا ہے۔ (مسلم: ۱۶۷۰) قریش کا واقعہ: سیدنا ابن عباس رضی اللہ عنہ فرماتے ہیں: دور جاہلیت میں سب سے پہلا قسامہ والا واقعہ ہمارے خاندان بنو ہاشم میں پیش آیا (بنو ہاشم قبیلہ قریش ہی کی ایک شاخ ہے) ہوایوں کہ قریش کے ایک دوسرے خاندان کے ایک شخص نے ایک ہاشمی شخص کو اجرت پر رکھا اور اپنے قافلے میں اسے ساتھ لے گیا، راستے میں اس ہاشمی شخص کے پاس سے ایک اور ہاشمی شخص گزرا اور اس نے اونٹ کا گھٹا باندھنے والی ایک رسی مانگ کر مدد چاہی، اس مزدور ہاشمی نے وہ اسے دے دی، چنانچہ وہ اسے لے کر چلا گیا۔ ادھر جب اہل قافلہ نے پڑاؤ کیا اور اونٹ باندھنے لگے تو ایک رسی کم نکلی تو اس غیر ہاشمی شخص نے ہاشمی شخص کو ڈنڈے سے مارا، جس کی بنا پر وہ موت کے قریب پہنچ گیا۔ ابھی اُس کے سانس باقی تھے کہ اتنے میں ایک یمنی شخص وہاں سے گزرا، ہاشمی نے اسے وصیت کی اور حج کے موقع پر ہاشمی سردار ابوطالب تک اس کے قتل کی اطلاع پہنچانے کا کہہ کر فوت ہو گیا۔ جب وہ غیر ہاشمی شخص واپس مکہ پہنچا تو ابوطالب نے اس سے پوچھا: وہ تمھارا ہاشمی مزدور کدھر ہے؟ اس نے کہا کہ وہ بیمار ہو گیا تھا، میں نے اس کی خوب دیکھ بھال کی لیکن وہ بالآخر فوت ہو گیا تو میں نے اسے وہیں دفنا دیا۔ ابوطالب کہنے لگے: تم سے اس کے ساتھ اسی بہترین سلوک کی امید تھی، پھر جب کچھ عرصے بعد حج کا موسم آیا اور یمنی شخص نے آکر ابوطالب کو مکمل صورتحال سے باخبر کیا کہ اس غیر ہاشمی نے محض ایک رسی کے بدلے تمھارا بندہ مار ڈالا تھا، تو ابوطالب اس کے پاس چلے گئے، اور اس سے کہا: تمھارے سامنے تین باتیں پیش کرتا ہوں تم ان میں سے کسی ایک کو چن لو، یا تو سو اونٹ دیت ادا کرو، یا پھر تمھارے خاندان کے پچاس آدمی یہ قسم کھائیں کہ تم نے اسے قتل نہیں کیا، یا پھر ہم تمھیں قصاص میں مار دیں گے۔ اس نے اپنے خاندان والوں سے بات کی تو وہ جھوٹی قسمیں کھانے کے لیے تیار ہو گئے۔ پھر ایک ہاشمی عورت جو اس خاندان میں بیاہی ہوئی تھی، اپنے ایک لڑکے کو لے کر ابوطالب کے پاس آئی اور کہنے لگی کہ میرے اس لڑکے کو معاف کر دیجیے اور جس جگہ قسمیں لی جاتی ہیں وہاں اسے قسم کھانے پر مجبور نہ کیجیے، انھوں نے اسے معاف کر دیا۔ ادھر ایک اور شخص آیا اور کہنے لگا: آپ نے سو اونٹوں کی جگہ پچاس قسمیں طلب کی ہیں اس کا مطلب یہ ہوا کہ ہر شخص پر دو اونٹ آتے ہیں تو آپ میری طرف سے یہ دو اونٹ قبول کر لیجیے اور مجھے قسم کھانے پر مجبور نہ کیجیے، ابوطالب نے اس کی بات بھی مان لی۔ باقی اڑتالیس آدمیوں نے جھوٹی قسمیں کھا لیں جس کی پاداش میں وہ سب سال گزرنے سے پہلے پہلے ہلاک ہو گئے۔ (بخاری: ۳۸۴۵، نسائی: ۴۷۱۰) دور فاروقی کا واقعہ: ایک واقعہ سیدنا عمر رضی اللہ عنہ کے دور میں پیش آیا جس کا پس منظر کچھ یوں تھا کہ دور جاہلیت میں ہذیل قبیلے نے اپنے ایک آدمی کو اپنے قبیلے سے نکال دیا تھا۔ کافی عرصے بعد وہ شخص مکہ آیا جہاں اہل یمن کے ایک گھرانے والوں کے پاس ان کے گھر میں وہ رات کے وقت داخل ہونے لگا تو گھر کے ایک شخص کی آنکھ کھل گئی اور اس نے تلوار کے ساتھ اسے مار ڈالا، اب اسی سے قطع تعلقی کرنے والا قبیلہ مدعی بن کر آ گیا اور یمنی آدمی کو پکڑ کر سیدنا عمر رضی اللہ عنہ کے پاس لے آیا اور کہنے لگا: اس نے ہمارا بندہ مارا ہے، اس قاتل نے کہا کہ ان کو اس مقتول سے کیا لینا دینا ہے، یہ تو اسے نکال چکے تھے، سیدنا عمر رضی اللہ عنہ نے پہلے اسی بات کا فیصلہ کرنا چاہا کہ یہ افراد اس مقتول کے مدعی بن بھی سکتے ہیں یا نہیں۔ انھوں نے فرمایا: ہذیل قبیلے کے پچاس آدمی یہ قسم کھائیں کہ ہم نے اسے نہیں نکالا تھا، چنانچہ ان میں سے انچاس نے قسمیں کھا لیں، ایک آدمی ملک شام گیا ہوا تھا، جب وہ آیا تو اسے قسم کھانے کے لیے کہا گیا، اس نے ہزار درہم دے کر قسم سے پیچھا چھڑا لیا۔ قبیلے والوں نے ایک اور شخص کو تیار کر لیا اور اس نے قسم کھا لی تو سیدنا عمر رضی اللہ عنہ نے وہ قاتل یمنی شخص مقتول ہذیلی آدمی کے بھائی کے سپرد کر دیا، اور اس کا ہاتھ اس کے ہاتھ کے ساتھ باندھ دیا گیا، گویا وہ اس کا قیدی بن گیا۔ وہ سب لوگ قسمیں کھا کر واپس ہوئے، ابھی مکہ سے نکل کر وادی نخلہ ہی میں پہنچے تھے کہ بارش شروع ہو گئی، وہ سب غار میں داخل ہو گئے تو غار ان پر گر پڑا اور پچاس کے پچاس دب کر مر گئے، البتہ جن دونوں کا ہاتھ بندھا ہوا تھا، وہ بچ گئے اور نکل بھاگے لیکن سال بعد وہ بھی مر گیا۔ (بخاری: ۶۸۹۹) یہ واقعہ ابوقلابہ رحمہ اللہ نے سنایا تھا۔ وہ دراصل قسامہ کے ساتھ قصاص واجب کرنے کے خلاف تھے۔ فیصلہ تو یہی ہے کہ پچاس آدمی خواہ کچی یا جھوٹی قسمیں کھا لیں گے تو مدعاعلیہ سے قصاص لازم ہو جائے گا لیکن ابوقلابہ رحمہ اللہ کا مقصد یہ تھا کہ عموماً ایسے مواقع پر خاندان کا ساتھ دیتے ہوئے جھوٹی قسمیں کھا لی جاتی ہیں جن کے نتیجے میں فوری تباہی مقدر ہو جاتی ہے۔ اس لیے تباہی کا سبب بننے والے اس کام کے قریب بھی نہ جانا چاہیے۔ انھوں نے یہ بھی بتایا کہ ایک دفعہ عبدالملک بن مروان رحمہ اللہ کے پچاس آدمیوں کی قسم پر قصاص دلا دیا، پھر وہ اس پر نادم ہوئے اور ان پچاس کو جھوٹا سمجھ کر ان کے نام تنخواہوں والے سرکاری رجسٹر سے خارج کر دیے اور انھیں ملک شام کی طرف جلا وطن کر دیا۔ (بخاری: ۶۸۹۹) سیدنا معاویہ رضی اللہ عنہ نے بھی اس کے ساتھ قصاص نہ دلایا تھا۔ (بخاری قبل از حدیث: ۶۸۹۸)۔ اگرچہ قسامہ مشروع ہے لیکن ابوقلابہ رحمہ اللہ، سالم رحمہ اللہ، سلیمان بن یسار رحمہ اللہ، حکم بن عتبہ، قتادہ، سفیان بن عیینہ، ابراہیم نخعی، امام بخاری، امام مسلم اور حضرت عمر بن عبدالعزیز رحمہ اللہ اس کے ساتھ فیصلہ کرنے سے گریز ہی کرتے تھے۔","§خلاصۃ الباب","اس باب میں دو احادیث نبویہ صلی اللہ علیہ وسلم ہیں جو بخاری و مسلم میں بھی موجود ہیں، نیز امام مالک رحمہ اللہ کے آٹھ فتاوی جات بھی مذکور ہیں۔","امام مالک رحمہ اللہ اور امام احمد رحمہ اللہ کے نزدیک سب سے پہلے مدعی قوم قسم کھائے گی اور ان کے قسمیں کھا لینے سے قتل خطا اور قتل شبہ عمد میں دیت جبکہ قتل عمد میں قصاص واجب ہو جائے گا اور اگر وہ قسمیں نہ کھائیں تو مدعاعلیہ قوم والے پچاس قسمیں کھا کر دیت اور قصاص سے بری ہو جائیں گے۔ اگر وہ مدعاعلیہ گروپ قسمیں نہ کھائے تو ان پر دیت لازم ہو جائے گی۔ امام شافعی رحمہ اللہ کا قدیم قول بھی یہی تھا، ان کا قول جدید یہ ہے کہ قتل عمد میں بھی مدعی قوم کی قسموں سے صرف دیت واجب ہوگی، ہاں اگر مدعی قسمیں نہ اٹھائیں تو مدعاعلیہ سے قسموں کا کہا جائے گا، اگر وہ قسمیں نہ کھائیں تو ان پر دیت لازم ہوگی اور اگر قسمیں کھا لیں تو دیت سے بری ہو جائیں گے۔۔۔۔۔ امام ابوحنیفہ رحمہ اللہ کے نزدیک یہ قسمیں خطا میں دیت اور قتل عمد میں قصاص لازم کرتی ہیں، اگر گواہ نہ ہوں تو مدعا علیہ قوم سے پچاس قسمیں لیں گے اور وہ قسمیں کھائیں یا نہ کھائیں ان پر ہر صورت میں صرف اور صرف دیت ہی لازم ہوگی۔ پہلا موقف راجح معلوم ہوتا ہے، کیونکہ وہ احادیث کے قریب تر ہے۔"],"597":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے سات فتاویٰ جات مذکور ہیں۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْأَمْرُ الَّذِي لَا اخْتِلَافَ فِيهِ عِنْدَنَا: أَنَّهُ لَا يَحْلِفُ فِي الْقَسَامَةِ فِي الْعَمْدِ أَحَدٌ مِنَ النِّسَاءِ، وَإِنْ لَمْ يَكُنْ لِلْمَقْتُولِ وَلَاةٌ إِلَّا النِّسَاءُ، فَلَيْسَ لِلنِّسَاءِ فِي قَتْلِ الْعَمْدِ قَسَامَةٌ وَلَا عَفْوٌ.","امام مالک رحمہ اللہ نے فرمایا: وہ حکم جس میں ہمارے ہاں کوئی اختلاف نہیں ہے، یہ ہے کہ بلاشبہ قتل عمد کی قسامت میں عورتوں میں سے کوئی بھی عورت قسم نہیں کھائے گی، اگرچہ مقتول کے لیے عورتوں کے سوا کوئی بھی وارث نہ ہوں۔ لہٰذا عورتوں کے لیے قتل عمد میں نہ تو قسامت اور نہ ہی معافی (کا اختیار) ہے۔","امام احمد رحمہ اللہ اور جمہور کا بھی یہی موقف ہے۔ احناف کے ہاں تو سرے سے مدعی پارٹی قسمیں دے ہی نہیں سکتی اور امام شافعی رحمہ اللہ کے ہاں قتل عمد ہو یا قتل خطا ہر دو میں عورتیں بھی قسمیں کھا سکتی ہیں، جمہور کا موقف راجح ہے۔","قَالَ يَحْيَى: قَالَ مَالِكٌ فِي الرَّجُلِ يُقْتَلُ عَمْداً: أَنَّهُ إِذَا قَامَ عَصَبَةُ الْمَقْتُولِ أَوْ مَوَالِيهِ فَقَالُوا: نَحْنُ نَحْلِفُ وَنَسْتَحِقُّ دَمَ صَاحِبِنَا، فَذَلِكَ لَهُمْ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق جو عمداً قتل کر دیا جاتا ہے، فرمایا: بلاشبہ جب مقتول کے عصبہ یا موالی (دعویٰ کرتے ہوئے) کھڑے ہوں اور کہیں کہ ہم قسمیں کھا لیتے ہیں اور اپنے صاحب (مقتول) کے خون (کے قصاص) کے مستحق بن جاتے ہیں تو یہ ان کے لیے جائز ہے۔","یہاں عصبہ سے مراد میت کے والد کی طرف سے مذکر رشتہ دار ہیں، خواہ انھیں وراثت ملے یا نہ ملے۔ امام احمد رحمہ اللہ کا بھی یہی موقف ہے، اور یہی راجح ہے۔ البتہ امام شافعی رحمہ اللہ کے نزدیک صرف وہ عصبہ قسمیں دیں گے، جنھیں مقتول کی وراثت میں سے حصہ بھی ملتا ہو... موالی سے مراد مقتول کا آزاد کرنے والا آقا اور اس آقا کے عصبہ رشتہ دار ہیں۔","قَالَ مَالِكٌ: فَإِنْ أَرَادَ النِّسَاءُ أَنْ يَعْفُونَ عَنْهُ، فَلَيْسَ ذَلِكَ لَهُنَّ.","امام مالک رحمہ اللہ نے فرمایا: اور اگر (مقتول کی وارث) عورتیں ارادہ کریں کہ وہ اس (کے خون) کو معاف کر دیں تو یہ ان کے لیے (جائز) نہیں ہے۔","قَالَ مَالِكٌ: الْعَصَبَةُ وَالْمَوَالِي أَوْلَى بِذَلِكَ","امام مالک رحمہ اللہ نے فرمایا: عصبہ (آبائی مذکر) رشتہ دار مِنْهُنَّ، لِأَنَّهُمْ هُمُ الَّذِينَ اسْتَحَقُّوا الدَّمَ وَحَلَفُوا عَلَيْهِ.","اور موالی (مقتول کے آزاد کرنے والے) ان عورتوں کی نسبت اس معافی کے زیادہ حقدار ہیں کیونکہ بلاشبہ وہی تو ہیں جو خون کے مستحق بنتے ہیں اور اس پر حلف دیتے ہیں۔","قَالَ مَالِكٌ: وَإِنْ عَفَتِ الْعَصَبَةُ أَوِ الْمَوَالِي بَعْدَ أَنْ يَسْتَحِقُّوا الدَّمَ، وَأَبَى النِّسَاءُ وَقُلْنَ: لَا نَدَعُ قَاتِلَ صَاحِبِنَا، فَهُنَّ أَحَقُّ وَأَوْلَى بِذَلِكَ، لِأَنَّ مَنْ أَخَذَ الْقَوَدَ أَحَقُّ مِمَّنْ تَرَكَهُ مِنَ النِّسَاءِ وَالْعَصَبَةِ، إِذَا ثَبَتَ الدَّمُ وَوَجَبَ الْقَتْلُ.","امام مالک رحمہ اللہ نے فرمایا: اور اگر عصبہ یا موالی نے (قسمیں کھا کر) خون کے مستحق بننے کے بعد اسے معاف کر دیا اور عورتوں نے (اس معافی سے) انکار کر دیا اور کہنے لگیں کہ ہم تو اپنے صاحب (مقتول) کے قاتل کو نہ چھوڑیں گی، تو وہ اس (قصاص) کی زیادہ حقدار اور زیادہ لائق ہیں کیونکہ یقیناً جب خون ثابت ہو جائے اور (قصاصاً) قتل واجب ہو جائے تو عورتوں اور عصبہ رشتہ داروں میں سے جو قصاص لینا چاہے وہ اس شخص کی نسبت زیادہ حقدار ہے جو قصاص چھوڑنا چاہے۔","یعنی قسمیں کھا لینے اور قصاص کا حق پا لینے کے بعد ان متولیوں اور وارثوں کی بات مانی جائے گی جو قصاص لینے پر اصرار کریں خواہ وہ عورتیں ہی ہوں اور اگر قصاص کا مستحق بننے سے پہلے ایک وارث بھی قصاص معاف کر دے تو پھر کسی کو قصاص لینے کی اجازت نہیں ملتی۔","قَالَ مَالِكٌ: لَا يُقْسِمُ فِي قَتْلِ الْعَمْدِ مِنَ الْمُدَّعِينَ إِلَّا اثْنَانِ فَصَاعِداً: تُرَدَّدُ الْأَيْمَانُ عَلَيْهِمَا حَتَّى يَحْلِفَا خَمْسِينَ يَمِيناً، ثُمَّ قَدِ اسْتَحَقَّا الدَّمَ، وَذَلِكَ الْأَمْرُ عِنْدَنَا.","امام مالک رحمہ اللہ نے فرمایا: بقتل عمد میں مدعی افراد سے قسم نہ لی جائے گی مگر کم از کم دو یا ان سے زیادہ سے (چنانچہ اگر قسم دینے والا مدعی صرف ایک فرد ہو تو پھر قتل عمد میں قسامت جائز ہی نہیں)، ان دونوں پر قسمیں لوٹائی جاتی رہیں گی، یہاں تک کہ وہ دونوں (ملا کر) پچاس قسمیں کھا لیں، پھر وہ دونوں اس خون کے مستحق قرار پائیں گے اور ہمارے ہاں یہی حکم ہے۔","قَالَ مَالِكٌ: وَإِذَا ضَرَبَ النَّفَرُ الرَّجُلَ حَتَّى يَمُوتَ تَحْتَ أَيْدِيهِمْ، قُتِلُوا بِهِ جَمِيعاً، فَإِنْ هُوَ مَاتَ بَعْدَ ضَرْبِهِمْ، كَانَتِ الْقَسَامَةُ، وَإِذَا كَانَتِ الْقَسَامَةُ لَمْ تَكُنْ إِلَّا عَلَى رَجُلٍ","امام مالک رحمہ اللہ نے فرمایا: اور جب (چند افراد کا ایک) گروہ کسی شخص کو مارے پیٹے، یہاں تک کہ وہ ان کے ہاتھوں کے نیچے مر جائے تو اس کے بدلے وہ سب قتل کیے جائیں گے، پھر (لیکن) اگر وہ ان کی ضربوں کے بعد (کسی وَاحِدٍ، وَلَمْ يُقْتَلْ غَيْرُهُ، وَلَمْ نَعْلَمْ قَسَامَةً كَانَتْ قَطُّ إِلَّا عَلَى رَجُلٍ وَاحِدٍ.","اور وقت) مرے تو قسامت (واجب) ہوگی اور جب قسامت (واجب) ہوگی تو وہ صرف ایک ہی شخص کے خلاف ہو سکتی ہے۔ اس ایک کے علاوہ کسی اور کو قتل نہ کیا جائے گا اور ہمیں کبھی کسی ایسی قسامت کا علم نہیں ہوا جو صرف ایک شخص پر نہ ہو۔","کسی روایت سے یہ ثابت نہیں ہو سکا کہ کسی موقع پر قسامت کی وجہ سے مارے جانے والے افراد ایک سے زائد ہوں، جو قسامت بھی ہوئی صرف ایک شخص کے خلاف قصاص ثابت کرنے کے لیے ہوئی اور اس کے ساتھ شریک دوسرے مجرموں کو صرف سو سو کوڑے اور ایک سال قید کی سزا دی جائے گی۔ (زرقانی: ۲۸۶/۴) مذکورہ بالا صورت میں امام ابو حنیفہ رحمہ اللہ اور امام شافعی رحمہ اللہ کا یہ موقف ہے کہ ان سب کے مارنے والوں سے قصاص ہوگا خواہ مقتول فوراً مرے یا بعد میں، اس میں قسامت نہ ہوگی، اور یہی موقف راجح ہے۔"],"598":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے دو فتاویٰ مذکور ہیں۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الْقَسَامَةُ فِي قَتْلِ الْخَطَإِ: يُقْسِمُ الَّذِينَ يَدَّعُونَ الدَّمَ وَيَسْتَحِقُّونَهُ بِقَسَامَتِهِمْ، يَحْلِفُونَ خَمْسِينَ يَمِيناً، تَكُونُ عَلَى قَسْمِ مَوَارِيثِهِمْ مِنَ الدِّيَةِ، فَإِنْ كَانَ فِي الْأَيْمَانِ كُسُورٌ إِذَا قُسِمَتْ بَيْنَهُمْ، نُظِرَ إِلَى الَّذِي يَكُونُ عَلَيْهِ أَكْثَرُ تِلْكَ الْأَيْمَانِ إِذَا قُسِمَتْ، فَتُجْبَرُ عَلَيْهِ تِلْكَ الْيَمِينُ.","امام مالک رحمہ اللہ نے قتل خطا میں قسامت کے متعلق فرمایا: (پہلے) وہ لوگ قسم کھائیں گے جو خون کا دعویٰ کریں (خواہ مرد ہوں یا عورتیں) اور وہ اپنی قسموں کے ساتھ اس (خون کی دیت) کے مستحق بن جائیں گے۔ وہ پچاس قسمیں کھائیں گے اور دیت میں سے ان کے وراثت کے حصوں کی تقسیم ہی کے مطابق ان پر وہ (قسمیں) پڑیں گی، (مثلاً مدعی دو بیٹے ہوں تو وہ پچیس پچیس قسمیں کھا لیں گے، ایک بیٹا اور تین بیٹیاں ہوں تو بیٹا بیس جبکہ بیٹیاں دس دس قسمیں کھا لیں گی) پھر جب قسمیں ان (ورثاء) پر تقسیم کی جائیں تو ان میں کسر واقع ہو جائے (یعنی حصوں کے مطابق تقسیم کر کے کچھ قسمیں باقی بچ جائیں اور ان کی تقسیم پوری پوری نہ ہو) تو پھر ان (ورثاء) کو دیکھا جائے گا جن پر تقسیم کرتے وقت ان قسموں کا زیادہ حصہ پڑتا ہے، تو انھی پر وہ (کسر والی یعنی باقی ماندہ قسمیں ڈال کر تقسیم) پوری کر دی جائے گی۔","مثلاً ورثاء میں صرف ماں، بیوی اور دو بیٹیاں ہوں تو ماں کو چھٹا حصہ، بیوی کو آٹھواں حصہ اور بیٹیوں کو وراثت میں سے دو تہائی ملے گا۔ چنانچہ ان میں وراثت تقسیم کرتے وقت کل چوبیس حصے بنائیں گے، چوبیس کے عدد میں سے یہ سب حصے پورے پورے نکل آتے ہیں، بایں طور کہ ماں کو چار، بیوی کو تین اور بیٹیوں کو سولہ حصے ملیں گے، لیکن خود چوبیس حصوں میں سے ایک باقی بچ جاتا ہے تو یہ حصہ بیٹیوں کے کھاتے میں ڈال دیا جائے گا۔","قَالَ مَالِكٌ: فَإِنْ لَمْ يَكُنْ لِلْمَقْتُولِ وَرَثَةٌ إِلَّا النِّسَاءُ، فَإِنَّهُنَّ يَحْلِفْنَ وَيَأْخُذْنَ الدِّيَةَ، فَإِنْ لَمْ يَكُنْ لَهُ وَارِثٌ إِلَّا رَجُلٌ وَاحِدٌ، حَلَفَ خَمْسِينَ يَمِيناً، وَأَخَذَ الدِّيَةَ، وَإِنَّمَا يَكُونُ ذَلِكَ فِي قَتْلِ الْخَطَإِ، وَلَا يَكُونُ فِي قَتْلِ الْعَمْدِ.","امام مالک رحمہ اللہ نے فرمایا: اور اگر عورتوں کے سوا مقتول کا کوئی اور وارث نہ ہو تو بلاشبہ وہ قسمیں کھا کر دیت لے لیں گی اور اگر صرف ایک مرد کے سوا کوئی اور وارث نہ ہو تو وہ بھی (اکیلا ہی) پچاس قسمیں کھا کر دیت لے لے گا اور بلاشبہ یہ صرف اور صرف قتل خطا میں (جائز) ہے اور قتل عمد میں (یہ درست) نہیں ہے۔"],"599":["قَالَ يَحْيَى: قَالَ مَالِكٌ: إِذَا قَبِلَ وَلَاةُ الدَّمِ الدِّيَةَ، فَهِيَ مَوْرُوثَةٌ عَلَى كِتَابِ اللَّهِ، يَرِثُهَا بَنَاتُ الْمَيِّتِ وَأَخَوَاتُهُ، وَمَنْ يَرِثُهُ مِنَ النِّسَاءِ، فَإِنْ لَمْ يُحْرِزِ النِّسَاءُ مِيرَاثَهُ، كَانَ مَا بَقِيَ مِنْ دِيَتِهِ لِأَوْلَى النَّاسِ بِمِيرَاثِهِ مَعَ النِّسَاءِ.","امام مالک رحمہ اللہ نے فرمایا: جب خون کے ورثاء دیت قبول کر لیں تو کتاب اللہ کے مطابق اس کا وارث بنا جائے گا۔ اسے میت کی بیٹیاں اور بہنیں وراثت میں پائیں گی اور وہ عورتیں بھی جو میت کی وارث بن سکتی ہیں، پھر اگر عورتیں اس کی وراثت کو مکمل نہ سمیٹ سکیں تو اس کی دیت میں سے جو کچھ باقی بچے گا، وہ اس قریبی شخص کے لیے ہوگا جو ان عورتوں کے ساتھ میت کی وراثت کا سب لوگوں سے زیادہ حقدار (یعنی میت کا سب سے قریبی مرد رشتہ دار عصبہ بن کر بقیہ ترکہ لے لے گا)۔","قَالَ مَالِكٌ: إِذَا قَامَ بَعْضُ وَرَثَةِ الْمَقْتُولِ الَّذِي يُقْتَلُ خَطَأً، يُرِيدُ أَنْ يَأْخُذَ مِنَ الدِّيَةِ بِقَدْرِ حَقِّهِ مِنْهَا وَأَصْحَابُهُ غَيْبٌ، لَمْ يَأْخُذْ ذَلِكَ، وَلَمْ يَسْتَحِقَّ مِنَ الدِّيَةِ شَيْئاً قَلَّ وَلَا كَثُرَ، دُونَ أَنْ يَسْتَكْمِلَ الْقَسَامَةَ، يَحْلِفُ","امام مالک رحمہ اللہ نے فرمایا: جب اس مقتول جسے خطا کے ساتھ قتل کر دیا جائے گا، کی دیت پانے والے ورثاء میں سے کوئی کھڑا ہو۔ وہ چاہتا ہو کہ دیت میں سے اپنے حصے کے بقدر لے لے، اس حال میں کہ اس کے باقی ساتھی غائب ہوں، تو وہ اسے نہیں لے سکتا اور قسامت کو مکمل کیے خَمْسِينَ يَمِيناً، فَإِنْ حَلَفَ خَمْسِينَ يَمِيناً اسْتَحَقَّ حِصَّتَهُ مِنَ الدِّيَةِ، وَذَلِكَ أَنَّ الدَّمَ لَا يَثْبُتُ إِلَّا بِخَمْسِينَ يَمِيناً، وَلَا تَثْبُتُ الدِّيَةُ حَتَّى يَثْبُتَ الدَّمُ، فَإِنْ جَاءَ بَعْدَ ذَلِكَ مِنَ الْوَرَثَةِ أَحَدٌ حَلَفَ مِنَ الْخَمْسِينَ يَمِيناً بِقَدْرِ مِيرَاثِهِ وَأَخَذَ حَقَّهُ، حَتَّى يَسْتَكْمِلَ الْوَرَثَةُ حُقُوقَهُمْ، إِنْ جَاءَ أَخٌ لِأُمٍّ فَلَهُ السُّدُسُ، وَعَلَيْهِ مِنَ الْخَمْسِينَ يَمِيناً السُّدُسُ، فَمَنْ حَلَفَ اسْتَحَقَّ حَقَّهُ مِنَ الدِّيَةِ، وَمَنْ نَكَلَ بَطَلَ حَقُّهُ، وَإِنْ كَانَ بَعْضُ الْوَرَثَةِ غَائِباً، أَوْ صَبِيَّا لَمْ يَبْلُغِ الْحُلُمَ، حَلَفَ الَّذِينَ حَضَرُوا خَمْسِينَ يَمِيناً، فَإِنْ جَاءَ الْغَائِبُ بَعْدَ ذَلِكَ، أَوْ بَلَغَ الصَّبِيُّ الْحُلُمَ، حَلَفَ كُلٌّ مِنْهُمَا، يَحْلِفُونَ عَلَى قَدْرِ حُقُوقِهِمْ مِنَ الدِّيَةِ وَعَلَى قَدْرِ مَوَارِيثِهِمْ مِنْهَا.","بغیر وہ دیت میں سے کسی چیز کا وارث نہیں بن سکتا، خواہ وہ قلیل ہو یا کثیر۔ (اسے چاہیے کہ) وہ پچاس قسمیں کھائے، چنانچہ جب وہ پچاس بار قسم اٹھائے گا تو دیت میں سے اپنے حصے کا مستحق ٹھہرے گا اور یہ (اکیلے کی پچاس قسمیں واجب ہونا) اس لیے ہے کہ پچاس قسموں کے بغیر خون ثابت نہیں ہو سکتا اور خون ثابت ہوئے بغیر دیت ثابت نہیں ہو سکتی، پھر اگر اس کے بعد ورثاء میں سے کوئی آ جائے تو وہ پچاس میں سے اتنی قسمیں کھائے گا جو اس کے حصہ وراثت کے بقدر ہوں اور وہ اپنا حصہ لے لے گا، یہاں تک کہ (اسی طریقے سے) ورثاء اپنے حقوق کو مکمل کر لیں۔ چنانچہ (اس کی مثال یہ ہے کہ) اگر ماں کی طرف سے (اخیافی) بھائی آ جائے تو اس کے لیے (وراثت کا) چھٹا حصہ ہے اور اس پر پچاس قسموں میں سے چھٹا حصہ پڑے گا (جو کہ تقریباً آٹھ بنتی ہیں)، پھر جو کوئی حلف اٹھا لے گا وہ دیت میں سے اپنے حق کا مستحق ہو جائے گا اور جو انکار کرے گا، اس کا حق باطل ہو جائے گا اور اگر ورثاء میں سے کوئی غائب ہو یا بچہ ہو یا ابھی بالغ نہ ہوا ہو تو جو لوگ حاضر ہیں وہ پچاس قسمیں کھا لیں، پھر اگر اس کے بعد وہ غائب آدمی آ جائے تو (اپنے حصے کے حساب سے) قسم اٹھائے یا بچہ بلوغت کی عمر کو پہنچ جائے تو وہ سب دیت میں سے اپنے حقوق کے حساب سے اور اس میں سے اپنے وراثت کے حصہ کے بقدر ہی قسمیں اٹھا لیں گے۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: وَهَذَا أَحْسَنُ مَا سَمِعْتُ.","امام مالک رحمہ اللہ نے فرمایا: اور یہ سب سے بہترین قول ہے جو میں نے اس بارے میں سنا ہے۔","چونکہ یہ قتل خطا کا بیان ہے جس کا معاملہ ذرا ہلکا ہوتا ہے اور پابندیاں کم ہوتی ہیں، اس میں اگر تو سارے ورثاء موجود ہیں تو اپنے اپنے حصے کے حساب سے اکٹھی قسمیں کھا لیں لیکن اگر بعض موجود نہ ہوں تو ان کے انتظار کی ضرورت نہیں۔ موجود ورثاء اپنا اپنا حصہ لے سکتے ہیں لیکن چونکہ دیت میں سے حصے لینے کے لیے دیت کو ثابت کرنا لازم ہے اور وہ پچاس قسمیں پوری ہونے سے ہی ثابت ہو سکتی ہے۔ اس لیے یہ موجود وارث، خواہ ایک ہی ہو، مجبوراً پچاس پوری پچاس قسمیں کھا لے، لیکن دیت میں سے صرف اپنا حصہ لے، باقی ورثاء آئیں گے تو ان کے اپنے حصے کی قسمیں دینا ہوں گی، کیونکہ ابتدائی پچاس قسمیں صرف مجبوراً کھائی گئی تھیں۔"],"600":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے دو فتاویٰ مذکور ہیں۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: الأَمْرُ عِنْدَنَا فِي الْعَبِيدِ: أَنَّهُ إِذَا أُصِيبَ الْعَبْدُ عَمْداً أَوْ خَطَأً ثُمَّ جَاءَ سَيِّدُهُ بِشَاهِدٍ حَلَفَ مَعَ شَاهِدِهِ يَمِيناً وَاحِدَةً، ثُمَّ كَانَ لَهُ قِيمَةُ عَبْدِهِ، وَلَيْسَ فِي الْعَبِيدِ قَسَامَةٌ، فِي عَمْدٍ وَلَا خَطَإٍ، وَلَمْ أَسْمَعْ أَحَداً مِنْ أَهْلِ الْعِلْمِ قَالَ ذَلِكَ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں غلام کے متعلق یہ حکم ہے کہ بلاشبہ جب غلام کو عمداً یا غلطی سے قتل کر دیا جائے، پھر اس کا آقا ایک گواہ لے آئے یا وہ اپنے گواہ کے ساتھ صرف ایک قسم کھائے گا (جس طرح کے عام معاملات میں ہوتا ہے کہ مدعی دو گواہ لائے، یا ایک گواہ اور ایک قسم پیش کرے) پھر اس کے لیے اس کے غلام کی قیمت واجب ہو جائے گی اور غلاموں میں قسامت نہیں ہے، نہ قتل عمد میں اور نہ قتل خطا میں، اور میں نے اہل علم میں سے کسی کو نہیں سنا جو اس (قسامت) کے قائل ہوں۔","امام ابو حنیفہ رحمہ اللہ اور امام شافعی رحمہ اللہ غلاموں میں بھی قسامت کے قائل ہیں۔","قَالَ مَالِكٌ: فَإِنْ قُتِلَ الْعَبْدُ عَمْداً أَوْ خَطَأً، لَمْ يَكُنْ عَلَى سَيِّدِ الْعَبْدِ الْمَقْتُولِ قَسَامَةٌ وَلَا يَمِينٌ، وَلَا يَسْتَحِقُّ سَيِّدُهُ ذَلِكَ إِلَّا بِبَيِّنَةٍ عَادِلَةٍ أَوْ بِشَاهِدٍ، فَيَحْلِفُ مَعَ شَاهِدِهِ.","امام مالک رحمہ اللہ نے فرمایا: اگر ایک غلام دوسرے غلام کو عمداً یا غلطی سے قتل کر دے تو مقتول غلام کے آقا پر نہ قسامت ہوگی اور نہ کوئی قسم، اس کا آقا اس (مقتول غلام کی قیمت) کا مستحق نہیں بن سکتا مگر عدل والی دلیل (اور ثبوت یعنی دو گواہوں) کے ساتھ یا ایک گواہ کے ساتھ، چنانچہ (ایک گواہ ہو تو) وہ اپنے گواہ کے ساتھ (ایک) قسم کھائے گا۔","قَالَ يَحْيَى: قَالَ مَالِكٌ: وَهَذَا أَحْسَنُ مَا سَمِعْتُ.","امام مالک رحمہ اللہ نے فرمایا: اور یہ سب سے بہترین بات ہے جو میں نے سنی ہے۔"],"601":["§کتاب کا تعارف","اس کتاب میں چھ ابواب اور بائیس روایات ہیں، جن میں سے نو مرفوع (احادیث نبویہ صلی اللہ علیہ وسلم) نو موقوف (آثار صحابہ رضی اللہ عنہم) اور چار مقطوع (آثار تابعین رحمہم اللہ) ہیں اور ان تمام میں سے سترہ صحیح اور پانچ ضعیف ہیں، چنانچہ ۹ مرفوع روایات میں سے ۸ صحیح اور ایک ضعیف ہے، ۹ موقوف روایات میں سے ۵ صحیح اور ۴ ضعیف ہیں اور چاروں مقطوع روایات سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے گیارہ فتاویٰ جات بھی اس کتاب میں مذکور ہیں۔","لفظ حدود ’’حد‘‘ کی جمع ہے جس کے معنی رکاوٹ کے ہیں، یہ حدود دراصل جرائم کے پھیلاؤ میں رکاوٹ ہوتی ہیں۔ اصطلاحاً اس سے مراد وہ سزا ہے جو اللہ تعالیٰ کا حق ہونے کی وجہ سے مقرر ہو، قصاص، حد قتل اور حد محاربہ (بغاوت) کے علاوہ جو بھی سزائیں قرآن وسنت میں مقرر ہیں انھیں حدود کہا جاتا ہے اور جو مقرر نہیں ہیں انھیں تعزیرات کہا جاتا ہے۔ حدود میں صرف تین سزائیں شامل ہیں: ۱- حد زنا سو کوڑے یا رجم، ۲- حد قذف یعنی تہمت زنا کی سزا اسی کوڑے، اور ۳- حد سرقہ یعنی چوری کی سزا ہاتھ کاٹنا۔ رہا شراب کا معاملہ تو اس کے متعلق راجح یہ ہے کہ وہ تعزیرات میں شامل ہے۔ امام مالک رحمہ اللہ نے اس مذکورہ کتاب میں صرف زنا اور تہمت زنا کے مسائل ذکر کیے ہیں، چوری اور شراب کا بیان آگے مستقل کتابوں میں آ رہا ہے۔","§خلاصۃ الباب","اس باب میں بارہ روایات ہیں، سات مرفوع یعنی احادیث نبویہ صلی اللہ علیہ وسلم، چار موقوف یعنی آثار صحابہ رضی اللہ عنہم اور ایک مقطوع یعنی اثر تابعی رحمہ اللہ ہے اور سب کی سب سنداً صحیح ہیں۔"],"602":["§خلاصۃ الباب","اس باب میں دو روایات ہیں: ایک مرفوع (حدیث نبوی صلی اللہ علیہ وسلم) اور ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے اور دونوں ہی سنداً ضعیف ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ بھی مذکور ہیں۔"],"603":["§خلاصۃ الباب","اس باب میں تین روایات ہیں، ایک مرفوع (حدیث نبوی صلی اللہ علیہ وسلم) ہے جو کہ بخاری ومسلم میں بھی موجود ہے اور دو موقوف (آثار صحابہ رضی اللہ عنہم) ہیں، جن میں سے ایک صحیح اور ایک ضعیف ہے۔"],"604":["§خلاصۃ الباب","اس باب میں امام مالک رحمہ اللہ کے دو فتاویٰ جات مذکور ہیں۔","غصب شدہ عورت سے مراد وہ عورت ہے جسے اغوا کر کے اس سے جنسی زیادتی کی جائے۔","قَالَ مَالِكٌ: الْأَمْرُ عِنْدَنَا فِي الْمَرْأَةِ تُوجَدُ حَامِلاً، وَلَا زَوْجَ لَهَا، فَتَقُولُ قَدِ اسْتُكْرِهْتُ، أَوْ تَقُولُ: تَزَوَّجْتُ: إِنَّ ذَلِكَ لَا يُقْبَلُ مِنْهَا، وَإِنَّهَا يُقَامُ عَلَيْهَا الْحَدُّ، إِلَّا أَنْ يَكُونَ لَهَا عَلَى مَا ادَّعَتْ مِنَ النِّكَاحِ بَيِّنَةٌ، أَوْ عَلَى أَنَّهَا اسْتُكْرِهَتْ، أَوْ جَاءَتْ تَدْمِي إِنْ كَانَتْ بِكْراً، أَوِ اسْتَغَاثَتْ حَتَّى أُتِيَتْ وَهِيَ عَلَى ذَلِكَ الْحَالِ، أَوْ مَا أَشْبَهَ هَذَا مِنَ الْأَمْرِ الَّذِي تَبْلُغُ فِيهِ فَضِيحَةَ نَفْسِهَا، قَالَ: فَإِنْ لَمْ تَأْتِ بِشَيْءٍ مِنْ هَذَا أُقِيمَ عَلَيْهَا الْحَدُّ، وَلَمْ يُقْبَلْ مِنْهَا مَا ادَّعَتْ مِنْ ذَلِكَ.","امام مالک رحمہ اللہ نے فرمایا: ہمارے ہاں اس عورت کے متعلق حکم یہ ہے جو حاملہ پائی جائے حالانکہ اس کا خاوند نہ ہو، پھر وہ کہے کہ میرے ساتھ زبردستی کی گئی تھی یا کہے کہ میں نے (پہلے کسی سے) شادی کی تھی تو بلاشبہ اس سے یہ قول قبول نہ کیا جائے گا اور بلاشبہ اس پر حد قائم کی جائے گی۔ الا یہ کہ اس نے جو نکاح کا دعویٰ کیا ہے اس پر اس کے پاس کوئی دلیل موجود ہو یا اس (دعویٰ) پر (دلیل ہو) کہ اس سے زبردستی کی گئی تھی یا اگر وہ کنواری تھی تو اس حال میں آئی کہ پردہ بکارت پھاڑے جانے سے خون جاری ہو یا وہ فریاد کرے (اور چیخے چلائے)۔ یہاں تک کہ جب اس کے پاس پہنچا جائے تو وہ اسی حال میں (چیخ و پکار کر رہی) ہو یا ان جیسا کوئی اور معاملہ ہو، جس میں اس کی ذاتی رسوائی ظاہر ہوتی ہو (اور ایسے قرائن و شواہد مل جائیں کہ جن سے اس کا مظلوم ہونا ظاہر ہو، تو یہ اس بات کی دلیل ہے کہ وہ اس کام پر راضی نہ تھی، ورنہ خود کو رسوا نہ کرتی)، چنانچہ اگر وہ اس (حمل کے معاملے) میں اس طرح کی چیز (دلیل) نہ لا سکے تو اس پر حد قائم کی جائے گی اور اس سے وہ دعویٰ قبول نہ ہوگا جو وہ کرے گی۔","قَالَ مَالِكٌ: وَالْمُعْتَصَبَةُ لَا تَنْكِحُ حَتَّى تَسْتَبْرِئَ نَفْسَهَا بِثَلَاثِ حِيَضٍ، فَإِنِ ارْتَابَتْ مِنْ حَيْضَتِهَا فَلَا تَنْكِحُ حَتَّى تَسْتَبْرِئَ نَفْسَهَا","امام مالک رحمہ اللہ نے فرمایا: اور غصب شدہ عورت (اس وقت تک) نکاح نہ کرے یہاں تک کہ وہ تین حیض کے ساتھ استبراء رحم (رحم کا حمل سے خالی ہونا) حاصل کر لے، چنانچہ مِنْ تِلْكَ الرِّيبَةِ.","اگر اسے اپنے حیض کا شبہ بھی ہو تو وہ نکاح نہ کرے یہاں تک کہ خود کو اس شک سے بری کر لے۔","چونکہ جب تک آزاد عورت یا لونڈی کے پیٹ میں کسی اور شخص کا بچہ ہو، تب تک خاوند یا مالک اس سے مباشرت نہیں کر سکتا۔ اس لیے یہ ضروری ہوتا ہے کہ شادی کے وقت عورت کا رحم یقینی طور پر حمل سے خالی ہو اور اس کا علم حیض کی آمد سے ہوتا ہے کیونکہ اگر حمل ہو تو حیض نہیں آتا۔ لونڈی کے بارے میں تو اتفاق ہے کہ اس کے لیے ایک حیض تک انتظار کیا جائے گا۔ رہا آزاد عورت کا معاملہ تو ہمارے نزدیک اس کے لیے بھی ایک حیض کا انتظار کافی ہے کیونکہ خلع کے مسئلے میں اس کی بھی وضاحت ہے کہ وہاں استبراء رحم کے لیے صرف ایک حیض کی مدت بطور عدت مقرر کی گئی ہے۔ (ابوداود: ۲۲۲۹، ۲۲۳۰، ترمذی: ۱۱۸۵، ابن ماجہ: ۲۰۵۸، ان سب کی سندیں صحیح ہیں)۔"],"605":["§خلاصۃ الباب","اس باب میں چار روایات ہیں، جن میں سے ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے، جو سنداً ضعیف ہے اور تین مقطوع (آثار تابعین رحمہم اللہ) ہیں جو سنداً صحیح ہیں، نیز امام مالک رحمہ اللہ کے چار فتاویٰ جات بھی مذکور ہیں۔","یہاں ’’نفی‘‘ سے مراد کسی کو یہ کہنا ہے کہ وہ اپنے باپ کا نہیں ہے، اور تعریض سے مراد ایسی گفتگو ہے جس میں زنا کے الزام کا کوئی اشارہ کنایہ ہو یا اس کے نتیجے میں زنا کی تہمت نکل رہی ہو۔"],"606":["§خلاصۃ الباب","اس باب میں ایک موقوف روایت (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے، نیز امام مالک رحمہ اللہ کے تین فتاویٰ جات بھی مذکور ہیں۔","قَالَ مَالِكٌ: إِنَّ أَحْسَنَ مَا سُمِعَ فِي الْأَمَةِ يَقَعُ بِهَا الرَّجُلُ وَلَهُ فِيهَا شِرْكٌ، أَنَّهُ لَا يُقَامُ عَلَيْهِ الْحَدُّ، وَأَنَّهُ يُلْحَقُ بِهِ الْوَلَدُ، وَتُقَوَّمُ عَلَيْهِ الْجَارِيَةُ حِينَ حَمَلَتْ، فَيُعْطَى شُرَكَاؤُهُ حِصَصَهُمْ مِنَ الثَّمَنِ، وَتَكُونُ الْجَارِيَةُ لَهُ، وَعَلَى هَذَا الْأَمْرُ عِنْدَنَا.","امام مالک رحمہ اللہ نے فرمایا: یقیناً سب سے بہترین بات جو اس لونڈی کی کہ جس سے آدمی مباشرت کرتا ہے اس حال میں کہ اس مرد کے ساتھ اس لونڈی میں (کچھ دوسرے آقاؤں کی بھی) شرکت ہے (کیونکہ مثلاً اسے مختلف آدمیوں نے مل کر خریدا تھا، تو سب سے بہترین بات جو ایسی لونڈی سے مباشرت کرنے والے آقا) کے متعلق سنی گئی ہے، یہ ہے کہ بلاشبہ اس پر حد قائم نہ کی جائے گی اور یقیناً (اگر اس مباشرت سے بچہ پیدا ہوا تو وہ) بچہ بھی اسی سے لاحق کیا جائے گا (اور بچے کا نسب اسی کے ساتھ جوڑ دیا جائے گا) اور (البتہ) اس شخص پر اس لونڈی کی قیمت لگائی جائے گی جس وقت کہ وہ حاملہ ہوگی۔ پھر اس قیمت میں اس سے اس کے شرکاء کو ان کے حصے ادا کیے جائیں گے اور وہ لونڈی اسی (اکیلے) کے لیے ہو جائے گی۔ امام مالک رحمہ اللہ نے فرمایا: اور ہمارے ہاں اسی کے مطابق حکم ہے۔","قَالَ مَالِكٌ فِي الرَّجُلِ يُحِلُّ لِلرَّجُلِ جَارِيَتَهُ: إِنَّهُ إِنْ أَصَابَهَا الَّذِي أُحِلَّتْ لَهُ قُوِّمَتْ عَلَيْهِ يَوْمَ أَصَابَهَا، حَمَلَتْ أَوْ لَمْ تَحْمِلْ، وَدُرِئَ عَنْهُ الْحَدُّ بِذَلِكَ، فَإِنْ حَمَلَتْ أُلْحِقَ بِهِ الْوَلَدُ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا: جو دوسرے آدمی کے لیے اپنی لونڈی حلال کر دیتا ہے (اگرچہ یہ درست نہیں ہے، یقیناً جس شخص کے لیے وہ حلال کی گئی ہے، اگر اس نے اس لونڈی سے مباشرت کر لی تو جس دن اس نے اس کے ساتھ مباشرت کی ہو، اس پر اسی دن (کے لحاظ سے) اس کی قیمت لگائی جائے گی۔ خواہ اسے حمل ٹھہرے یا نہ ٹھہرے اور اس طریقے سے اس سے حد ہٹا دی جائے گی (چنانچہ اس دوسرے شخص کو زانی شمار نہ کیا جائے گا)۔ پھر اگر وہ حاملہ ہو جائے تو بچہ اس (دوسرے شخص) کے ساتھ لاحق کر دیا جائے گا۔","قَالَ مَالِكٌ فِي الرَّجُلِ يَقَعُ عَلَى جَارِيَةِ ابْنِهِ أَوِ ابْنَتِهِ: أَنَّهُ يُدْرَأُ عَنْهُ الْحَدُّ، وَتُقَوَّمُ عَلَيْهِ الْجَارِيَةُ، حَمَلَتْ أَوْ لَمْ تَحْمِلْ.","امام مالک رحمہ اللہ نے اس شخص کے متعلق فرمایا: جو اپنے بیٹے یا اپنی بیٹی کی لونڈی کے ساتھ مباشرت کر لیتا ہے بلاشبہ اس سے بھی حد ہٹا دی جائے گی اور لونڈی کی اس (باپ) پر قیمت لگائی جائے گی، اور باپ کے ذمے ہوگا کہ اس لونڈی کی قیمت اپنے بیٹے یا بیٹی کو دے کر اپنی ملکیت بنالے خواہ اسے حمل ٹھہرے یا نہ ٹھہرے۔","در اصل رسول اللہ صلی اللہ علیہ وسلم کا فرمان مبارک ہے: ’’تو (بھی) اور تیرا مال (بھی) تیرے والد ہی کا (مال اور کمائی) ہے۔‘‘ (ابو داود: ۳۵۳۰، ابن ماجہ: ۲۲۹۲۔ اس کی سند صحیح ہے)۔ تو اگرچہ باپ نے شریعت کا طریقہ اختیار نہیں کیا بلکہ اس کی خلاف ورزی کی ہے۔ لیکن چونکہ ایک لحاظ سے وہ اس کا اپنا مال ہی تھا، اس لیے اس پر حد نہیں ہوگی۔"],"607":["§کتاب کا تعارف","اس کتاب میں پانچ ابواب اور سولہ روایات ہیں، جن میں سے چار مرفوع (احادیث نبویہ صلی اللہ علیہ وسلم)، آٹھ موقوف (آثار صحابہ رضی اللہ عنہم) اور چار مقطوع (آثار تابعین رحمہم اللہ) ہیں اور ان سولہ میں سے بارہ سنداً صحیح، ایک حسن اور تین ضعیف ہیں۔ چنانچہ چار مرفوع روایات میں سے تین صحیح ہیں اور ایک حسن ہے۔ آٹھ موقوف روایات میں سے چھ صحیح اور دو ضعیف ہیں اور چار مقطوع روایات میں سے تین صحیح ہیں اور ایک ضعیف ہے۔ نیز امام مالک رحمہ اللہ کے اٹھارہ فتاویٰ جات بھی اس کتاب میں مذکور ہیں۔","§خلاصۃ الباب","اس باب میں پانچ روایات ہیں، جن میں سے دو مرفوع ہیں اور ان میں سے ایک سنداً صحیح اور ایک حسن ہے اور تین موقوف ہیں جو سنداً صحیح ہیں۔ نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","جمہور یعنی امام مالک رحمہ اللہ، امام شافعی رحمہ اللہ، امام احمد رحمہ اللہ اور اہلحدیث کے نزدیک چوری کا نصاب وہی ہے جو احادیث مبارکہ میں بیان ہوا ہے یعنی سونے کے دینار کا چوتھائی حصہ یا چاندی کے تین درہم۔ رسول اللہ صلی اللہ علیہ وسلم کے دور میں ان دونوں مقداروں کی قیمت برابر برابر تھی، بعد میں ان کے مابین فرق پڑتا گیا اور آج کل تو زمین و آسمان جیسا فرق پڑ چکا ہے۔ اگر سونے کا حساب لگائیں تو اس کا بھاؤ دسمبر ۲۰۱۴ء تک اڑتالیس ہزار روپے فی تولہ کے لگ بھگ ہے جبکہ صرف تین چار سال قبل اس کی قیمت ساٹھ ہزار پاکستانی روپے سے بھی زیادہ تھی۔ رہی چاندی تو وہ تقریباً سات سو روپے تولہ ہے، اور کچھ عرصہ قبل ایک ہزار روپے فی تولہ تھی۔۔۔۔۔ دور نبوی صلی اللہ علیہ وسلم کا ایک دینار چونکہ چار ماشے اور چار رتی کے برابر تھا۔ اس لیے سونے کے حساب سے چوری کا نصاب ایک ماشہ اور ایک رتی یعنی چوتھائی دینار ہے۔ ایک تولے میں بارہ ماشے ہوتے ہیں، یوں آج کل کے حساب سے سونے کا ایک ماشہ تقریباً چار ہزار روپے اور ایک رتی پانچ سو روپے کے برابر ہے۔ لہٰذا سونے کے حساب سے ہاتھ کاٹنے کا حساب ساڑھے چار ہزار روپے کے لگ بھگ ہے۔ اگر چاندی کا حساب لگائیں تو چونکہ دور نبوی صلی اللہ علیہ وسلم کا ایک درہم تین ماشے، ایک رتی اور رتی کے پانچویں حصے کے برابر تھا، اس لیے چاندی کے اعتبار سے چور کا ہاتھ تقریباً ساڑھے نو ماشے چاندی پر کٹے گا۔ چاندی کے ایک ماشے کی قیمت ساٹھ روپے سے بھی کم ہے اور رتی کی قیمت آٹھ روپے بھی نہیں بنتی۔ الغرض تین درہم یعنی تقریباً ساڑھے نو ماشے چاندی کی قیمت ساڑھے پانچ سو روپے کے لگ بھگ بنتی ہے۔ اس لیے جو شخص اتنی مالیت کی چوری کرے گا تو اس کا ہاتھ کاٹا جائے گا۔"],"608":["§خلاصۃ الباب","اس باب میں تین روایات ہیں جن میں سے ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے اور وہ سنداً صحیح ہے، جبکہ دو روایات مقطوع (آثار تابعین رحمہم اللہ) ہیں، جن میں سے ایک صحیح اور ایک ضعیف ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی اس میں مذکور ہے۔","اس باب میں اس غلام کا بیان ہے جو دو خرابیوں کا مرتکب ہو، بھاگا ہوا بھی ہو اور چور بھی ہو تو یہاں یہ بتایا جا رہا ہے کہ محض بھاگنے کے جرم میں تو ہاتھ نہ کٹے گا، البتہ اگر نصاب کو پہنچنے والی چوری کرے گا تو پھر اس پر حد نافذ ہوگی، ورنہ نہیں۔"],"609":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک مرفوع (حدیث نبوی صلی اللہ علیہ وسلم) اور ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے اور دونوں ہی سنداً صحیح ہیں۔"],"610":["§خلاصۃ الباب","اس باب میں دو روایات ہیں، ایک موقوف (اثر صحابی رضی اللہ عنہ) ہے جو سنداً ضعیف ہے اور دوسری مقطوع (اثر تابعی رحمہ اللہ) ہے جو سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کے دس فتاویٰ جات بھی اس باب میں مذکور ہیں۔"],"611":["§خلاصۃ الباب","اس باب میں چار روایات ہیں، ایک مرفوع (حدیث نبوی صلی اللہ علیہ وسلم) ہے جو سنداً صحیح ہے، دو موقوف (آثار صحابہ رضی اللہ عنہم) ہیں جن میں سے ایک صحیح اور ایک ضعیف ہے، اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے جو کہ صحیح ہے، نیز امام مالک رحمہ اللہ کے چھ فتاویٰ جات بھی مذکور ہیں۔"],"612":["§کتاب کا تعارف","اس کتاب میں پانچ ابواب اور پندرہ روایات ہیں، جن میں سے نو مرفوع (احادیث نبویہ صلی اللہ علیہ وسلم) اور پانچ موقوف (آثار صحابہ رضی اللہ عنہم) ہیں اور ایک مقطوع (اثر تابعی رحمہ اللہ) ہے اور یہ تمام روایات سنداً صحیح ہیں، سوائے دو موقوف روایات کے جو کہ ضعیف ہیں، نیز امام مالک رحمہ اللہ کے دو فتاویٰ جات بھی مذکور ہیں۔","§خلاصۃ الباب","اس میں چار روایات ہیں، تین موقوف ہیں، جن میں سے ایک صحیح اور دو ضعیف ہیں اور ایک روایت مقطوع ہے جو کہ سنداً صحیح ہے، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","جمہور کے ہاں ہر قسم کی شراب اور نشہ آور اشیاء کا حکم یکساں ہے اور وہ حرام ہیں۔ نشہ آور مشروبات کو کم پیا جائے یا زیادہ، اس سے نشہ ہو یا نہ، ہر صورت میں حد خمر (شراب کی حد) لاگو ہوگی۔ جبکہ احناف کے نزدیک اصل شراب صرف اور صرف انگور کی ہے جس کی کم یا زیادہ ہر مقدار حرام ہے اور اس کے علاوہ باقی ہر شراب اور نشہ آور چیز میں حرمت کا سبب نشہ کا وجود ہے۔ چنانچہ ان کے نزدیک ان چیزوں کا استعمال جائز ہے اور جس گھونٹ پر نشہ چڑھنے لگے وہ حرام ہے۔"],"613":["§خلاصۃ الباب","اس باب میں دو مرفوع روایات (احادیث نبویہ صلی اللہ علیہ وسلم) ہیں جو کہ صحیح ہیں، نیز امام مالک رحمہ اللہ کا ایک فتویٰ بھی مذکور ہے۔","نبیذ سے مراد یہ ہے کہ کشمش یا کھجور کو پانی میں بھگودیا جائے اور پھر چند گھنٹے بعد اسے پانی میں حل کر کے چھان کر یا بغیر چھانے شربت بنالیا جائے، بشرطیکہ اس میں نہ تیزی آئی ہو اور نہ جھاگ۔۔۔۔۔ یہ تو سب علماء کے ہاں درست ہے۔ کچھ لوگ دودھ میں بھی نبیذ بنا لیتے ہیں۔ یاد رہے کہ پانی میں انھیں بھگونے کے بعد سے لے کر چوبیس گھنٹے تک اس کے استعمال کی اجازت ہے، بعض روایات میں تین دن رات کا بھی تذکرہ ہے۔ (مسلم: ۲۰۰۴) معلوم ہوتا ہے کہ بعض موسموں میں نبیذ تین دن رات تک نشہ آور نہیں ہوتا، بہر حال جیسے ہی اس میں جھاگ اور تیزی آئے تو اسے ضائع کر دینا چاہیے۔"],"614":["§خلاصۃ الباب","اس باب میں دو احادیث نبویہ صلی اللہ علیہ وسلم مذکور ہیں جو کہ بخاری ومسلم میں بھی موجود ہیں۔"],"615":["§خلاصۃ الباب","اس باب میں تین مرفوع روایات (احادیث نبویہ صلی اللہ علیہ وسلم) ہیں جو سنداً صحیح ہیں۔ بعض نسخوں میں یہ باب اس کتاب کا آخری باب ہے، اس صورت میں اس باب کی کل روایات سات ہوں گی۔","جمہور کے ہاں ہر قسم کی شراب اور نشہ آور اشیاء یکساں درجے کی حرام ہیں، انھیں کم پیا جائے یا زیادہ، ان سے نشہ چڑھے یا نہ، ان کا قلیل وکثیر حرام اور موجب سزا ہے۔ جبکہ احناف کے ہاں انگور کی شراب میں تو یہی جمہور والا فیصلہ ہے لیکن باقی اشیاء میں وہ کہتے ہیں کہ جب تک نشہ نہ چڑھے انھیں استعمال کیا جاسکتا ہے اور صرف وہ جزو حرام ہے جس سے نشہ چڑھتا ہو۔ لیکن ان کا یہ موقف صریح صحیح احادیث نبویہ کے خلاف ہے۔ چنانچہ فرمان نبوی صلی اللہ علیہ وسلم ہے: ’’ہر نشہ آور چیز خمر (شراب) ہے اور ہر شراب حرام ہے۔‘‘ (مسلم: ۲۰۰۳) سیدنا ابو ہریرہ رضی اللہ عنہ نے شراب کی وضاحت میں انگور کے ساتھ کھجور کا بھی ذکر کیا۔ (مسلم: ۱۹۸۵) سیدنا انس رضی اللہ عنہ کہتے ہیں کہ حرمت شراب کے وقت ہمارے پاس انگوروں کی شراب تو کم ہی تھی، ہماری عام شراب کچی کھجور اور خشک کھجور سے تیار ہوتی تھی۔ (بخاری: ۵۵۸۰) سیدنا عمر رضی اللہ عنہ نے منبر رسول اللہ صلی اللہ علیہ وسلم پر اعلان فرمایا: جب شراب حرام ہوئی تو وہ پانچ چیزوں سے تیار ہوا کرتی تھی: انگور، کھجور، گندم، جو اور شہد۔ خمر یعنی شراب ہر وہ چیز ہے جو عقل کو مخمور کر دے یعنی ڈھانپ لے۔ (بخاری: ۵۵۸۸) رسول اللہ صلی اللہ علیہ وسلم نے مکئی کی شراب کو بھی حرام قرار دیا۔ (مسلم: ۲۰۰۲) نیز فرمایا: ’’جس چیز کے تین صاع (تقریباً سات کلوگرام) پینے سے نشہ ہوتا ہو، اس کا ایک چلو بھی حرام ہے۔‘‘ (ابوداود: ۳۶۸۷، ترمذی: ۱۸۶۶۔ اس کی سند صحیح ہے) نیز فرمایا: ’’جس چیز کو زیادہ پینے سے نشہ آتا ہو اس کی تھوڑی سی مقدار بھی حرام ہے۔‘‘ (ابوداود: ۳۶۸۱، ترمذی: ۱۸۶۵، ابن ماجہ: ۳۳۹۳۔ اس کی سند صحیح ہے۔)"],"616":["§خلاصۃ الباب","اس باب میں چار روایات ہیں، دو مرفوع احادیث نبویہ صلی اللہ علیہ وسلم اور دو موقوف (آثار صحابہ رضی اللہ عنہم) ہیں اور سب سنداً صحیح ہیں۔"],"617":["§کتاب کا تعارف","اس کتاب میں اٹھاسی (۸۸) ابواب اور دوسوساٹھ (۲۶۰) روایات ہیں جن میں سے ۱۸۳ مرفوع (احادیث نبویہ صلی اللہ علیہ وسلم)، ۵۶ موقوف (آثار صحابہ رضی اللہ عنہم) اور ۲۱ مقطوع (آثار تابعین رحمہم اللہ) ہیں اور ان تمام کے مجموعے میں سے ۲۰۶ سنداً صحیح، ۱۲ حسن اور ۴۲ ضعیف ہیں۔ چنانچہ ۱۸۳ مرفوع روایات میں سے ۱۵۹ صحیح، ۷ حسن اور ۱۷ ضعیف ہیں۔ ۵۶ موقوف روایات میں سے ۳۴ صحیح، ۴ حسن اور ۱۸ ضعیف ہیں اور ۲۱ مقطوع روایات میں سے ۱۳ صحیح، ایک حسن اور ۷ ضعیف ہیں۔ نیز امام مالک رحمہ اللہ کے بارہ فتاویٰ جات بھی اس کتاب میں مذکور ہیں۔","امام مالک رحمہ اللہ نے اتنی جامعیت کے ساتھ اس کتاب میں مختلف موضوعات کو سمیٹا ہے کہ بعد والے محدثین نے ان پر مستقل کتابوں کے عنوانات قائم کر کے انھیں سینکڑوں احادیث سے مزین کیا ہے۔ مثلاً کتاب فضائل المدينة، القدر، الآداب، الزينة، اللباس، صفة النبی صلی اللہ علیہ وسلم، الفطرة، الاطعمة، الاشربة، بدء الخلق، المرض، الطب، الرؤيا، السلام، الفتن، الرقاق، السفر، البيعة، الكلام، العلم وغیرہ۔ اٹھاسی ابواب پر مشتمل اس پوری کتاب کا باہمی ربط کچھ یوں محسوس ہوتا ہے کہ (۱-۹) موطا کی پوری کتاب میں مذکور اسلامی تعلیمات کے اجراء اور تنفیذ کے لیے ایک اسلامی معاشرے کی ضرورت ہے۔ اسی مناسبت سے کتاب الجامع کا آغاز مدینہ منورہ سے کیا جو پیغمبر اسلام صلی اللہ علیہ وسلم کے ہاتھوں سے تعمیر شدہ ایک مثالی اسلامک سٹیٹ تھی اور ہے۔ پھر اہل اسلام کے اس دینی مرکز کے متعلقہ چند فضائل و مسائل ذکر کیے، ایک فضیلت یہ ہے کہ یہاں طاعون داخل نہیں ہوسکتا۔ اس لیے ساتویں باب میں طاعون کا تذکرہ کیا، طاعون کی آزمائش تقدیر الہی سے تعلق رکھتی ہے، چنانچہ دو ابواب میں مسئلہ تقدیر ذکر کیا۔ (۱۰-۱۳) اب اسلامی معاشرے کے آداب بیان کرنا شروع کیے، جو معاشرے کے حسن وزینت کا باعث ہیں، تقدیر کی مناسبت سے چار ابواب میں سب سے پہلے فطری و جبلی اوصاف ذکر کیے، جن میں سے دو ممدوح ہیں: خوش خلقی اور حیا، پھر ایک مذموم وصف یعنی غضب اور اس کے نتیجے میں پیدا شدہ ناچاقی و قطع تعلقی کا ذکر کیا۔ (۱۴-۴۱) بعد ازاں معاشرے کی بنیادی اکائی (افراد معاشرہ) یعنی انسان کی بنیادی ضروریات (لباس، طعام اور علاج) تین حصوں میں بیان کیں، چنانچہ (۱۴-۲۱) جبلی فطرت ’’حیا‘‘ کا تقاضا لباس ہے اس لیے آٹھ ابواب میں لباس کا بیان کیا۔ (۲۲-۲۴) لباس کی طرح چونکہ حلیہ بھی ظاہری ہیئت سے تعلق رکھتا ہے، اس لیے مثال کے طور پر دو پیغمبروں کا حلیہ دو ابواب میں ذکر کیا اور ان کی مناسبت سے تیسرے پیغمبر حضرت ابراہیم علیہ السلام کا کچھ تذکرہ کیا اور ان چند امور کا بیان کیا جو اگرچہ انسان کی فطرت میں شامل ہیں، جن میں سے بعض کا آغاز حضرت ابراہیم علیہ السلام سے ہوا۔ (۲۵-۳۲) لباس وحلیہ کے بعد انسان کی دوسری بنیادی ضرورت کھانے پینے سے متعلقہ احکامات آٹھ ابواب میں ذکر کیے۔ (۳۳) اس کے بعد انگوٹھی پہننے کا ذکر کیا جس کے لیے مناسب مقام تو لباس والے ابواب تھے لیکن شاید اسے اس لیے مؤخر کیا کہ اسے بھی بسا اوقات کسی طبی نقطہ نگاہ سے پہنا جاتا ہے۔ واللہ اعلم (۳۴-۴۱) بعد ازاں علاج معالجہ (طب) کا بیان ہے جس میں علاج کے بعض ممنوع طریقے مذکور ہیں جیسا کہ جانوروں کو نظر بد سے بچانے کے لیے ان کے گلے میں مختلف چیزیں ڈالی جاتی ہیں۔ (۴۲-۴۴) پھر جسم انسانی ہی سے متعلقہ چیز بالوں کا بیان ہے۔ (۴۵-۴۸) بکھرے اور الجھے ہوئے بالوں کو شیطانی حلیے سے تعبیر کیا گیا تھا، اس لیے باب: ۴۵ میں شیطان سے پناہ کا ذکر ہے۔ پھر باب ۴۶ میں شیطان کے مقابلے میں رحمان کے محبوبوں کا تذکرہ ہے اور باب: ۴۷ میں خوابوں کا بیان ہے جو رحمان یا شیطان کی طرف سے ہوتے ہیں۔ نیز باب: ۴۶ کی آخری روایت کے مطابق بعض اوصاف اجزائے نبوت میں سے ہیں اسی طرح اچھے خواب بھی جزو نبوت ہیں۔ بعد ازاں باب: ۴۸ میں ایک شیطانی کھیل کا بیان ہے۔ (۴۹-۵۳) انسان کی انفرادی زندگی کے بعد اجتماعی زندگی اور افراد معاشرہ کے باہمی حقوق مذکور ہیں۔ مثلاً سلام اور چھینک کا جواب دینا، سلام کی مناسبت سے گھروں میں داخلے کی اجازت کا بھی بیان ساتھ ہی مذکور ہے۔ (۵۴) رحمت الہیہ اور مسرت ملائکہ والے امور کے بعد تصویروں کا بیان کیا جو برکتوں اور رحمتوں سے محروم کر دیتی ہیں۔ (۵۵-۶۳) انسانی معاشرے میں کچھ جانور بھی رہتے ہیں، اس لیے چند ابواب میں چند جانوروں کا ذکر ہے، ضمناً باب: ۵۹ میں نحوست کا بیان ہے جس کا تعلق بعض جانوروں سے بھی جوڑا جاتا ہے، پھر جس طرح نحوست پکڑنا ناجائز و ناپسندیدہ چیز ہے اسی طرح دو ابواب میں ناپسندیدہ ناموں اور مکروہ کمائی کا بیان ہے اور پھر اس خطے کی طرف اشارہ ہے جو ناپسندیدہ امور یعنی فتنوں کی آماجگاہ ہے۔ (۶۴-۶۹) بعد ازاں باہمی میل جول کی خاطر کیے جانے والے سفر کے آداب، دورانِ سفر خدمت کے لیے ساتھ لے جائے جانے والے غلاموں لونڈیوں اور اکٹھے سفر میں امیر بنانے اور امیر کی بیعت کرنے کا تذکرہ ہے۔ (۷۰-۷۷) پھر معاشرتی اصلاح یا بگاڑ کی کنجی یعنی زبان اور اس کی آفات کا بیان ہے۔ (۷۸-۸۰) پھر معاشرے کی تباہی کا سبب ذکر کیا کہ بسا اوقات فرد واحد کا قول و فعل عظیم وبال بن جاتا ہے، اس لیے ساتھ ہی اللہ سے ڈرنے کا ذکر کیا اور بتایا کہ گرج چمک بھی دراصل اللہ سے ڈرانے کا باعث ہے۔ (۸۱-۸۸) تقریباً اخیر میں اس ہستی کی وفات کا تذکرہ ہے جس کے شہر کے تذکرے سے کتاب الجامع کا آغاز ہوا تھا۔ چنانچہ شاہ مدینہ کی وفات ذکر کر کے سمجھایا کہ ہر کسی کو آخر مرنا ہے اس لیے اخروی زندگی کی تیاری کر لو اور جہنم سے بچنے کا انتظام کر لو۔ پھر خصوصاً تین اعمال ذکر کیے جو جہنم سے بچاؤ کا ذریعہ ہیں: (۱) صدقہ وخیرات (۲) حصول علم جو بہترین صدقہ جاریہ بھی ہے اور (۳) ظلم سے اجتناب اور کتاب کا اختتام تاجدار مدینہ صلی اللہ علیہ وسلم کے مبارک ناموں سے کیا۔","§خلاصۃ الباب","اس باب میں دو مرفوع روایات یعنی احادیث نبویہ صلی اللہ علیہ وسلم ہیں اور دونوں بخاری و مسلم کی روایات میں سے ہیں۔"]})